"use client";

import { useRender } from "@base-ui/react/use-render";
import { createContext, useContext, useEffect, useLayoutEffect, useRef, useState } from "react";
import { useMarkdownEditor } from "./markdown-editor/context";
import { MarkdownEditorDragHandle } from "./markdown-editor/drag/drag-handle";
import { createLiveEditor, type LiveEditor } from "./markdown-editor/live/live-engine";
import { LiveTaskCheckboxes } from "./markdown-editor/live/preview/task-checkboxes";
import { TaskCheckboxes } from "./markdown-editor/live/preview/widgets";
import { type MarkdownEditorContentProps, MarkdownEditorRoot, type MarkdownEditorRootProps } from "./markdown-editor/root";
import { MarkdownEditorSourceView } from "./markdown-editor/source-view";
import { MarkdownEditorTableControls } from "./markdown-editor/table/table-controls";
import { persistentUrlPolicy } from "./markdown-editor/url-policy";

export type {
  MarkdownEditorContentProps,
  MarkdownEditorRootProps as MarkdownEditorProps,
  MarkdownEditorStatus,
} from "./markdown-editor/root";

const LiveEditorContext = createContext<{ live: LiveEditor | null; tasks: TaskCheckboxes } | null>(null);

function useLiveEditor() {
  const context = useContext(LiveEditorContext);
  if (!context) throw new Error("MarkdownEditorContent requires a MarkdownEditor parent from the same module.");
  return context;
}

export function MarkdownEditor({ isUrlAllowed: urlPolicy = persistentUrlPolicy, ...props }: MarkdownEditorRootProps) {
  const [isUrlAllowed] = useState(() => urlPolicy);
  const [initial] = useState(() => ({ markdown: props.value ?? props.defaultValue ?? "", editable: !props.disabled && !props.readOnly }));
  const [tasks] = useState(() => new TaskCheckboxes());
  const [live, setLive] = useState<LiveEditor | null>(null);
  useEffect(() => {
    const editor = createLiveEditor(initial.markdown, initial.editable, { isUrlAllowed, tasks });
    setLive(editor);
    return () => editor.destroy();
  }, [initial, isUrlAllowed, tasks]);
  return (
    <LiveEditorContext value={{ live, tasks }}>
      <MarkdownEditorRoot engine={live?.engine ?? null} isUrlAllowed={isUrlAllowed} {...props} />
    </LiveEditorContext>
  );
}

export function MarkdownEditorContent({ label, placeholder, autoFocus = false, ref, ...props }: MarkdownEditorContentProps) {
  const container = useRef<HTMLDivElement>(null);
  const host = useRef<HTMLDivElement>(null);
  const { live, tasks } = useLiveEditor();
  const { disabled, readOnly, source } = useMarkdownEditor();
  const content = useRender({
    ref: [container, ref ?? null],
    render: (
      <div data-control-ui="markdown-editor" data-control-family="markdown-editor" data-slot="content" {...props}>
        <div ref={host} />
        <MarkdownEditorDragHandle container={container} />
        <MarkdownEditorTableControls container={container} />
        <LiveTaskCheckboxes registry={tasks} />
      </div>
    ),
  });

  useLayoutEffect(() => {
    const node = host.current;
    if (!(node && live)) return;
    node.append(live.view.dom);
    live.view.requestMeasure();
    return () => live.view.dom.remove();
  }, [live]);

  useEffect(() => {
    live?.configure({
      attributes: {
        role: "textbox",
        "aria-multiline": "true",
        "aria-label": label,
        "aria-disabled": String(disabled),
        "aria-readonly": String(readOnly),
        spellcheck: "true",
        autocorrect: "on",
        autocapitalize: "sentences",
      },
      placeholder: placeholder ?? "",
    });
  }, [live, label, disabled, readOnly, placeholder]);

  useEffect(() => {
    live?.configure({ preview: !source });
  }, [live, source]);

  useEffect(() => {
    if (live && autoFocus && !disabled) live.focusEnd();
  }, [live, autoFocus, disabled]);

  if (!live) return <MarkdownEditorSourceView ref={ref} label={label} placeholder={placeholder} autoFocus={autoFocus} {...props} />;
  return content;
}

import { isolateHistory } from "@codemirror/commands";
import { type EditorState, type Extension, StateEffect, StateField, type Text } from "@codemirror/state";
import { Decoration, EditorView, layer, RectangleMarker, ViewPlugin } from "@codemirror/view";
import { createDragPreview, type DragPreview } from "../../drag/drag-preview";
import type { MarkdownBlocks } from "../../engine";
import { type BlockMove, blockAt, blockStartingAt, dropBlock, type MarkdownBlockUnit, moveBlock, siblingBlocks } from "./block-model";

type BlockDrag = { unit: MarkdownBlockUnit | null; gap: number | null };

const liftBlock = StateEffect.define<MarkdownBlockUnit | null>();
const aimGap = StateEffect.define<number | null>();
const blockMime = "application/x-control-ui-markdown-block";
const lifted = Decoration.line({ class: "cm-md-lifted" });

const blockDrag = StateField.define<BlockDrag>({
  create: () => ({ unit: null, gap: null }),
  update(value, transaction) {
    let next = value;
    if (next.unit && transaction.docChanged) {
      next = { ...next, unit: { from: transaction.changes.mapPos(next.unit.from), to: transaction.changes.mapPos(next.unit.to, -1) } };
    }
    for (const effect of transaction.effects) {
      if (effect.is(liftBlock)) next = { unit: effect.value, gap: null };
      else if (effect.is(aimGap)) next = { ...next, gap: effect.value };
    }
    return next;
  },
  provide: (field) =>
    EditorView.decorations.compute([field], (state) => {
      const { unit } = state.field(field);
      return unit ? Decoration.set(linesOf(state.doc, unit).map((line) => lifted.range(line))) : Decoration.none;
    }),
});

function linesOf(doc: Text, unit: MarkdownBlockUnit) {
  const starts: number[] = [];
  for (let number = doc.lineAt(unit.from).number; number <= doc.lineAt(unit.to).number; number++) starts.push(doc.line(number).from);
  return starts;
}

function blockBox(view: EditorView, unit: MarkdownBlockUnit) {
  return { top: view.documentTop + view.lineBlockAt(unit.from).top, bottom: view.documentTop + view.lineBlockAt(unit.to).bottom };
}

function gapLines(view: EditorView, siblings: readonly MarkdownBlockUnit[]) {
  const boxes = siblings.map((sibling) => blockBox(view, sibling));
  return boxes.map((box, index) => (index === 0 ? box.top : (boxes[index - 1].bottom + box.top) / 2)).concat(boxes.at(-1)?.bottom ?? 0);
}

function nearestGap(view: EditorView, unit: MarkdownBlockUnit, clientY: number) {
  const lines = gapLines(view, siblingBlocks(view.state, unit));
  let gap = 0;
  for (let index = 1; index < lines.length; index++) {
    if (Math.abs(clientY - lines[index]) < Math.abs(clientY - lines[gap])) gap = index;
  }
  return lines.length > 0 ? gap : null;
}

const dropLine = layer({
  above: true,
  class: "cm-md-drop-layer",
  markers(view) {
    const { unit, gap } = view.state.field(blockDrag);
    if (!unit || gap === null) return [];
    const siblings = siblingBlocks(view.state, unit);
    const y = gapLines(view, siblings)[gap];
    const first = siblings[0];
    if (y === undefined || !first) return [];
    const scroller = view.scrollDOM.getBoundingClientRect();
    const content = view.contentDOM.getBoundingClientRect();
    const start = view.coordsAtPos(first.from)?.left ?? content.left;
    const end = content.right - Number.parseFloat(getComputedStyle(view.contentDOM).paddingInlineEnd);
    const left = start - scroller.left + view.scrollDOM.scrollLeft;
    const top = y - scroller.top + view.scrollDOM.scrollTop - 1;
    return [new RectangleMarker("cm-md-drop-line", left, top, Math.max(0, end - start), 2)];
  },
  update: (update) => update.startState.field(blockDrag) !== update.state.field(blockDrag) || update.geometryChanged,
});

function dispatchMove(view: EditorView, move: BlockMove, effects: StateEffect<unknown>[] = []) {
  view.dispatch({
    changes: move.changes,
    selection: move.selection,
    effects,
    annotations: isolateHistory.of("full"),
    scrollIntoView: true,
    userEvent: "move.block",
  });
}

function aimAt(view: EditorView, event: DragEvent) {
  const { unit, gap } = view.state.field(blockDrag);
  if (!unit) return;
  event.preventDefault();
  event.stopPropagation();
  if (event.dataTransfer) event.dataTransfer.dropEffect = "move";
  const next = nearestGap(view, unit, event.clientY);
  if (next !== gap) view.dispatch({ effects: aimGap.of(next) });
}

function leave(view: EditorView, event: DragEvent) {
  const { unit, gap } = view.state.field(blockDrag);
  if (!unit || gap === null || (event.relatedTarget instanceof Node && view.contentDOM.contains(event.relatedTarget))) return;
  view.dispatch({ effects: aimGap.of(null) });
}

function drop(view: EditorView, event: DragEvent) {
  const { unit, gap } = view.state.field(blockDrag);
  if (!unit) return;
  event.preventDefault();
  event.stopPropagation();
  const block = blockStartingAt(view.state, unit.from);
  const move = block && gap !== null ? dropBlock(view.state, block, gap) : null;
  if (move) dispatchMove(view, move, [liftBlock.of(null)]);
  else view.dispatch({ effects: liftBlock.of(null) });
  view.focus();
}

/** Captures block drags before CodeMirror or a table cell editor can treat them as text drops. */
const dropTarget = ViewPlugin.define((view) => {
  const dom = view.contentDOM;
  const over = (event: DragEvent) => aimAt(view, event);
  const out = (event: DragEvent) => leave(view, event);
  const land = (event: DragEvent) => drop(view, event);
  dom.addEventListener("dragover", over, true);
  dom.addEventListener("dragleave", out, true);
  dom.addEventListener("drop", land, true);
  return {
    destroy() {
      dom.removeEventListener("dragover", over, true);
      dom.removeEventListener("dragleave", out, true);
      dom.removeEventListener("drop", land, true);
    },
  };
});

export const blockDragging: Extension = [blockDrag, dropLine, dropTarget];

type PreparedDrag = { unit: MarkdownBlockUnit; document: Text; text: string; preview: DragPreview | null };

function lineElements(view: EditorView, unit: MarkdownBlockUnit) {
  const elements = new Set<HTMLElement>();
  for (const start of linesOf(view.state.doc, unit)) {
    const { node } = view.domAtPos(start);
    const element = node instanceof Element ? node : node.parentElement;
    const line = element?.closest(".cm-line");
    if (line instanceof HTMLElement) elements.add(line);
  }
  return Array.from(elements);
}

function prepare(view: EditorView, block: number): PreparedDrag | null {
  const unit = blockStartingAt(view.state, block);
  if (!unit) return null;
  return {
    unit,
    document: view.state.doc,
    text: view.state.sliceDoc(unit.from, unit.to),
    preview: createDragPreview(lineElements(view, unit), "cm-content"),
  };
}

function rectOf(view: EditorView, state: EditorState, block: number) {
  const unit = blockStartingAt(state, block);
  if (!unit) return null;
  const { top, bottom } = blockBox(view, unit);
  const content = view.contentDOM.getBoundingClientRect();
  return new DOMRect(content.left, top, content.width, bottom - top);
}

export function createLiveBlocks(view: EditorView): MarkdownBlocks {
  let prepared: PreparedDrag | null = null;
  return {
    at(point) {
      const position = view.posAtCoords(point, false);
      return blockAt(view.state, position)?.from ?? null;
    },
    atSelection: () => blockAt(view.state, view.state.selection.main.head)?.from ?? null,
    rect: (block) => rectOf(view, view.state, block),
    select(block) {
      const unit = blockStartingAt(view.state, block);
      if (unit) view.dispatch({ selection: { anchor: unit.from, head: unit.to } });
    },
    move(block, direction) {
      const unit = blockStartingAt(view.state, block);
      const move = unit ? moveBlock(view.state, unit, direction) : null;
      if (!move) return null;
      dispatchMove(view, move);
      return move.selection.anchor;
    },
    prepareDrag(block) {
      prepared = prepare(view, block);
    },
    startDrag(block, transfer) {
      const payload = prepared?.unit.from === block && prepared.document === view.state.doc ? prepared : prepare(view, block);
      prepared = null;
      if (!payload) return null;
      transfer.clearData();
      transfer.setData("text/plain", payload.text);
      transfer.setData(blockMime, "");
      transfer.effectAllowed = "copyMove";
      const origin = rectOf(view, view.state, block) ?? new DOMRect();
      view.dispatch({ effects: liftBlock.of(payload.unit) });
      return { preview: payload.preview, origin };
    },
    endDrag() {
      prepared = null;
      if (view.state.field(blockDrag, false)?.unit) view.dispatch({ effects: liftBlock.of(null) });
    },
  };
}

import { syntaxTree } from "@codemirror/language";
import type { EditorState, Text } from "@codemirror/state";
import type { SyntaxNode } from "@lezer/common";
import type { TextChange } from "../format/inline";

export type MarkdownBlockUnit = { from: number; to: number };
export type BlockMove = { changes: TextChange[]; selection: { anchor: number; head: number } };

type UnitNode = { unit: MarkdownBlockUnit; node: SyntaxNode };
type Arrangement = { order: number[]; gaps: string[] };

const containerName = /^(?:BulletList|OrderedList|ListItem|Blockquote)$/;
const verbatimBlock = /^(?:FencedCode|CodeBlock|HTMLBlock)$/;

const contains = (unit: MarkdownBlockUnit, pos: number) => unit.from <= pos && pos <= unit.to;

const linePrefix = (doc: Text, pos: number) => doc.sliceString(doc.lineAt(pos).from, pos);

function isBlankInside(text: string, quoteDepth: number): boolean {
  let rest = text;
  for (let depth = 0; depth < quoteDepth; depth++) {
    const marker = /^\s*>/.exec(rest);
    if (marker === null) break;
    rest = rest.slice(marker[0].length);
  }
  return rest.trim() === "";
}

function unitOf(doc: Text, node: SyntaxNode): MarkdownBlockUnit {
  const first = doc.lineAt(node.from);
  const quoteDepth = linePrefix(doc, node.from).split(">").length - 1;
  const end = node.to > node.from && doc.lineAt(node.to).from === node.to ? node.to - 1 : node.to;
  let last = doc.lineAt(end);
  while (last.number > first.number && isBlankInside(last.text, quoteDepth)) last = doc.line(last.number - 1);
  return { from: first.from, to: last.to };
}

// An item sharing its first line with its parent's marker ("1. - a") cannot move on its own.
const isMovableItem = (doc: Text, node: SyntaxNode) =>
  node.name === "ListItem" && node.parent !== null && /^[\s>]*$/.test(linePrefix(doc, node.parent.from));

function deepestItem(doc: Text, node: SyntaxNode, pos: number): SyntaxNode | null {
  for (let child = node.firstChild; child !== null; child = child.nextSibling) {
    if (!containerName.test(child.name) || !contains(unitOf(doc, child), pos)) continue;
    return deepestItem(doc, child, pos) ?? (isMovableItem(doc, child) ? child : null);
  }
  return null;
}

function children(node: SyntaxNode): SyntaxNode[] {
  const nodes: SyntaxNode[] = [];
  for (let child = node.firstChild; child !== null; child = child.nextSibling) nodes.push(child);
  return nodes;
}

function isBlankOutsideCode(state: EditorState, pos: number): boolean {
  if (state.doc.lineAt(pos).text.trim() !== "") return false;
  for (let node: SyntaxNode | null = syntaxTree(state).resolveInner(pos, 1); node !== null; node = node.parent) {
    if (verbatimBlock.test(node.name)) return false;
  }
  return true;
}

function locate(state: EditorState, pos: number): UnitNode | null {
  if (isBlankOutsideCode(state, pos)) return null;
  const doc = state.doc;
  const lineEnd = doc.lineAt(pos).to;
  for (let node = syntaxTree(state).topNode.firstChild; node !== null && node.from <= lineEnd; node = node.nextSibling) {
    const unit = unitOf(doc, node);
    if (!contains(unit, pos)) continue;
    const item = deepestItem(doc, node, pos);
    return item === null ? { unit, node } : { unit: unitOf(doc, item), node: item };
  }
  return null;
}

export function blockAt(state: EditorState, pos: number): MarkdownBlockUnit | null {
  return locate(state, pos)?.unit ?? null;
}

export function blockStartingAt(state: EditorState, from: number): MarkdownBlockUnit | null {
  if (from < 0 || from > state.doc.length) return null;
  const unit = blockAt(state, from);
  return unit !== null && unit.from === from ? unit : null;
}

function siblingNodes(state: EditorState, block: MarkdownBlockUnit): UnitNode[] {
  const located = locate(state, block.from);
  if (located === null || located.unit.from !== block.from) return [];
  const container = located.node.name === "ListItem" ? located.node.parent : null;
  const nodes = container === null ? children(syntaxTree(state).topNode) : children(container).filter((node) => node.name === "ListItem");
  return nodes.map((node) => ({ unit: unitOf(state.doc, node), node }));
}

export function siblingBlocks(state: EditorState, block: MarkdownBlockUnit): MarkdownBlockUnit[] {
  return siblingNodes(state, block).map((sibling) => sibling.unit);
}

function gapsBetween(doc: Text, siblings: UnitNode[]): string[] {
  return siblings.slice(1).map((sibling, index) => doc.sliceString(siblings[index].unit.to, sibling.unit.from));
}

function markerDigits(doc: Text, item: SyntaxNode): { offset: number; digits: string } | null {
  const mark = item.firstChild;
  if (mark === null || mark.name !== "ListMark") return null;
  const digits = /^\d+/.exec(doc.sliceString(mark.from, mark.to));
  return digits === null ? null : { offset: mark.from - doc.lineAt(item.from).from, digits: digits[0] };
}

function isOrderedList(siblings: UnitNode[]): boolean {
  const list = siblings[0].node.parent;
  return siblings[0].node.name === "ListItem" && list !== null && list.name === "OrderedList";
}

function arrangedTexts(doc: Text, siblings: UnitNode[], order: number[]): string[] {
  const texts = order.map((index) => doc.sliceString(siblings[index].unit.from, siblings[index].unit.to));
  if (!isOrderedList(siblings)) return texts;
  const start = Number(markerDigits(doc, siblings[0].node)?.digits ?? "1");
  return texts.map((text, position) => {
    const marker = markerDigits(doc, siblings[order[position]].node);
    if (marker === null) return text;
    return text.slice(0, marker.offset) + String(start + position) + text.slice(marker.offset + marker.digits.length);
  });
}

function changedSpan(arrangement: Arrangement, gaps: string[], renumbered: boolean): { first: number; last: number } {
  if (renumbered) return { first: 0, last: arrangement.order.length - 1 };
  let first = arrangement.order.length;
  let last = -1;
  const touch = (low: number, high: number) => {
    first = Math.min(first, low);
    last = Math.max(last, high);
  };
  arrangement.order.forEach((index, position) => {
    if (index !== position) touch(position, position);
  });
  arrangement.gaps.forEach((gap, position) => {
    if (gap !== gaps[position]) touch(position, position + 1);
  });
  return { first, last };
}

function minimalChange(from: number, before: string, after: string): TextChange[] {
  const shorter = Math.min(before.length, after.length);
  let prefix = 0;
  while (prefix < shorter && before[prefix] === after[prefix]) prefix++;
  let suffix = 0;
  while (suffix < shorter - prefix && before[before.length - 1 - suffix] === after[after.length - 1 - suffix]) suffix++;
  if (prefix === before.length && prefix === after.length) return [];
  return [{ from: from + prefix, to: from + before.length - suffix, insert: after.slice(prefix, after.length - suffix) }];
}

function applyArrangement(state: EditorState, siblings: UnitNode[], arrangement: Arrangement, moved: number): BlockMove {
  const doc = state.doc;
  const gaps = gapsBetween(doc, siblings);
  const renumbered = isOrderedList(siblings);
  const texts = arrangedTexts(doc, siblings, arrangement.order);
  const { first, last } = changedSpan(arrangement, gaps, renumbered);
  const from = siblings[first].unit.from;
  const to = siblings[last].unit.to;
  let insert = "";
  let selection = { anchor: from, head: from };
  for (let position = first; position <= last; position++) {
    if (position > first) insert += arrangement.gaps[position - 1];
    if (arrangement.order[position] === moved) {
      const anchor = from + insert.length;
      selection = { anchor, head: anchor + texts[position].length };
    }
    insert += texts[position];
  }
  return { changes: minimalChange(from, doc.sliceString(from, to), insert), selection };
}

export function moveBlock(state: EditorState, block: MarkdownBlockUnit, direction: -1 | 1): BlockMove | null {
  const siblings = siblingNodes(state, block);
  const index = siblings.findIndex((sibling) => sibling.unit.from === block.from);
  const target = index + direction;
  if (index < 0 || target < 0 || target >= siblings.length) return null;
  const order = siblings.map((_, position) => position);
  order[index] = target;
  order[target] = index;
  return applyArrangement(state, siblings, { order, gaps: gapsBetween(state.doc, siblings) }, index);
}

export function dropBlock(state: EditorState, block: MarkdownBlockUnit, index: number): BlockMove | null {
  const siblings = siblingNodes(state, block);
  const own = siblings.findIndex((sibling) => sibling.unit.from === block.from);
  if (own < 0 || !Number.isInteger(index) || index < 0 || index > siblings.length || index === own || index === own + 1) return null;
  const gaps = gapsBetween(state.doc, siblings);
  const removedGap = own < gaps.length ? own : own - 1;
  const ownSeparator = gaps[removedGap];
  const restOrder = siblings.map((_, position) => position).filter((position) => position !== own);
  const restGaps = gaps.filter((_, position) => position !== removedGap);
  const target = index > own ? index - 1 : index;
  const order = [...restOrder.slice(0, target), own, ...restOrder.slice(target)];
  return applyArrangement(state, siblings, { order, gaps: gapsAfterDrop(restGaps, ownSeparator, target) }, own);
}

/** The dropped block brings its separator to either end; in the middle it copies the gap before it. */
function gapsAfterDrop(restGaps: string[], ownSeparator: string, target: number): string[] {
  if (target === 0) return [ownSeparator, ...restGaps];
  if (target === restGaps.length + 1) return [...restGaps, ownSeparator];
  return [...restGaps.slice(0, target), restGaps[target - 1], ...restGaps.slice(target)];
}

import { syntaxTree } from "@codemirror/language";
import { type ChangeSet, EditorSelection, type EditorState, type Line, type StateCommand, type Transaction } from "@codemirror/state";
import type { SyntaxNode } from "@lezer/common";
import type { MarkdownBlockCommand, MarkdownBlockType, MarkdownHeadingLevel, MarkdownTextRange } from "../../engine";
import { codeBlockAt, type TextChange } from "./inline";

type LineParts = { lead: string; list: string; task: string; heading: string; rest: string };
type ListKind = "bulletList" | "orderedList" | "taskList";

const linePattern = /^(\s*(?:>[ \t]?)*[ \t]*)(?:((?:[-*+]|\d+[.)])(?:[ \t]+|$))(\[[ xX]\](?:[ \t]+|$))?)?(#{1,6}(?:[ \t]+|$))?/;
const sides: readonly (-1 | 1)[] = [1, -1];
const fence = "```";
const tableTemplate = createTableMarkdown(3, 2);

function createTableMarkdown(columns: number, bodyRows: number): string {
  const row = `|${"  |".repeat(columns)}`;
  const delimiter = `|${" --- |".repeat(columns)}`;
  return [row, delimiter, ...Array.from({ length: bodyRows }, () => row)].join("\n");
}

function parseLine(text: string): LineParts {
  const match = linePattern.exec(text);
  const lead = match?.[1] ?? "";
  const list = match?.[2] ?? "";
  const task = match?.[3] ?? "";
  const heading = match?.[4] ?? "";
  return { lead, list, task, heading, rest: text.slice(lead.length + list.length + task.length + heading.length) };
}

function listKind(parts: LineParts): ListKind | null {
  if (!parts.list) return null;
  if (parts.task) return "taskList";
  return /^\d/.test(parts.list) ? "orderedList" : "bulletList";
}

const isBlank = (line: Line) => line.text.trim() === "";

function linesBetween(state: EditorState, from: number, to: number): Line[] {
  const first = state.doc.lineAt(from);
  let last = state.doc.lineAt(to);
  if (to > from && to === last.from && last.number > first.number) last = state.doc.line(last.number - 1);
  const lines: Line[] = [];
  for (let number = first.number; number <= last.number; number++) lines.push(state.doc.line(number));
  return lines;
}

function touchedLines(state: EditorState): Line[] {
  const byNumber = new Map<number, Line>();
  for (const range of state.selection.ranges) {
    for (const line of linesBetween(state, range.from, range.to)) byNumber.set(line.number, line);
  }
  return [...byNumber.values()].sort((a, b) => a.number - b.number);
}

function contentLines(lines: Line[]): Line[] {
  const filled = lines.filter((line) => !isBlank(line));
  return filled.length > 0 ? filled : lines;
}

function ancestors(state: EditorState, pos: number): SyntaxNode[] {
  const nodes: SyntaxNode[] = [];
  for (const side of sides) {
    for (let node: SyntaxNode | null = syntaxTree(state).resolveInner(pos, side); node; node = node.parent) nodes.push(node);
  }
  return nodes;
}

export function activeBlocks(state: EditorState): Record<MarkdownBlockType, boolean> {
  const nodes = ancestors(state, state.selection.main.head);
  const names = new Set(nodes.map((node) => node.name));
  const item = nodes.find((node) => node.name === "ListItem");
  const task = Boolean(item?.getChild("Task"));
  return {
    bulletList: item?.parent?.name === "BulletList" && !task,
    orderedList: item?.parent?.name === "OrderedList",
    taskList: task,
    blockquote: names.has("Blockquote"),
    codeBlock: names.has("FencedCode") || names.has("CodeBlock"),
  };
}

export function headingLevel(state: EditorState): MarkdownHeadingLevel | null {
  for (const node of ancestors(state, state.selection.main.head)) {
    const level = /^(?:ATXHeading|SetextHeading)([1-6])$/.exec(node.name)?.[1];
    if (level) return toHeadingLevel(Number(level));
  }
  return null;
}

function toHeadingLevel(level: number): MarkdownHeadingLevel | null {
  switch (level) {
    case 1:
    case 2:
    case 3:
    case 4:
    case 5:
    case 6:
      return level;
    default:
      return null;
  }
}

function dispatchChanges(
  state: EditorState,
  dispatch: ((tr: Transaction) => void) | undefined,
  changes: TextChange[],
  selection?: (set: ChangeSet) => EditorSelection,
): boolean {
  if (!dispatch || changes.length === 0) return true;
  const set = state.changes(changes);
  const mapped = selection
    ? selection(set)
    : EditorSelection.create(
        state.selection.ranges.map((range) => EditorSelection.range(set.mapPos(range.anchor, 1), set.mapPos(range.head, 1))),
        state.selection.mainIndex,
      );
  dispatch(state.update({ changes: set, selection: mapped, scrollIntoView: true, userEvent: "input.format" }));
  return true;
}

function listMarker(kind: ListKind, parts: LineParts, number: number): string {
  if (kind === "orderedList") return `${number}. `;
  if (kind === "bulletList") return "- ";
  return parts.task ? `- ${parts.task.trimEnd()} ` : "- [ ] ";
}

function listChanges(state: EditorState, kind: ListKind): TextChange[] {
  const lines = contentLines(touchedLines(state)).filter((line) => !codeBlockAt(state, line.from));
  const unwrap = lines.length > 0 && lines.every((line) => listKind(parseLine(line.text)) === kind);
  return lines.map((line, index) => {
    const parts = parseLine(line.text);
    const from = line.from + parts.lead.length;
    return { from, to: from + parts.list.length + parts.task.length, insert: unwrap ? "" : listMarker(kind, parts, index + 1) };
  });
}

function quoteChanges(state: EditorState): TextChange[] {
  const lines = touchedLines(state);
  const quoted = (line: Line) => /^\s*>/.test(line.text);
  if (lines.every(quoted)) {
    return lines.map((line) => {
      const match = /^(\s*)> ?/.exec(line.text);
      const indent = match?.[1].length ?? 0;
      return { from: line.from + indent, to: line.from + (match?.[0].length ?? 0), insert: "" };
    });
  }
  const onlyBlank = lines.every(isBlank);
  return lines.map((line) => ({ from: line.from, to: line.from, insert: isBlank(line) && !onlyBlank ? ">" : "> " }));
}

function unwrapCodeBlock(state: EditorState, block: SyntaxNode): TextChange[] {
  if (block.name === "CodeBlock") {
    return linesBetween(state, block.from, block.to).map((line) => {
      const indent = /^ {0,4}/.exec(line.text)?.[0].length ?? 0;
      return { from: line.from, to: line.from + indent, insert: "" };
    });
  }
  const opening = state.doc.lineAt(block.from);
  const changes: TextChange[] = [{ from: opening.from, to: Math.min(opening.to + 1, state.doc.length), insert: "" }];
  const closingMark = block.lastChild;
  if (closingMark && closingMark.name === "CodeMark" && closingMark.from > opening.to) {
    const closing = state.doc.lineAt(closingMark.from);
    changes.push({ from: Math.max(closing.from - 1, opening.to + 1), to: closing.to, insert: "" });
  }
  return changes;
}

function wrapInCodeBlock(state: EditorState, dispatch: ((tr: Transaction) => void) | undefined): boolean {
  const main = state.selection.main;
  const lines = linesBetween(state, main.from, main.to);
  const first = lines[0];
  const last = lines[lines.length - 1];
  if (!first || !last) return true;
  if (lines.every(isBlank)) {
    const changes = [{ from: first.from, to: last.to, insert: `${fence}\n\n${fence}` }];
    return dispatchChanges(state, dispatch, changes, () => EditorSelection.single(first.from + fence.length + 1));
  }
  const changes: TextChange[] = lines.map((line) => {
    const parts = parseLine(line.text);
    const marked = parts.lead.includes(">") || parts.list !== "" || parts.heading !== "";
    const stripped = isBlank(line) || !marked ? 0 : line.length - parts.rest.length;
    return { from: line.from, to: line.from + stripped, insert: line === first ? `${fence}\n` : "" };
  });
  changes.push({ from: last.to, to: last.to, insert: `\n${fence}` });
  const mapPos = (set: ChangeSet, pos: number) => set.mapPos(pos, pos === last.to ? -1 : 1);
  return dispatchChanges(state, dispatch, changes, (set) =>
    EditorSelection.create(
      state.selection.ranges.map((range) => EditorSelection.range(mapPos(set, range.anchor), mapPos(set, range.head))),
      state.selection.mainIndex,
    ),
  );
}

export function toggleBlock(block: MarkdownBlockType): StateCommand {
  return ({ state, dispatch }) => {
    if (state.readOnly) return false;
    const code = codeBlockAt(state, state.selection.main.head);
    if (block === "codeBlock")
      return code ? dispatchChanges(state, dispatch, unwrapCodeBlock(state, code)) : wrapInCodeBlock(state, dispatch);
    if (code?.name === "FencedCode") return true;
    return dispatchChanges(state, dispatch, block === "blockquote" ? quoteChanges(state) : listChanges(state, block));
  };
}

const headingMarker = (level: MarkdownHeadingLevel | null) => (level ? `${"#".repeat(level)} ` : "");

function atxChange(line: Line, level: MarkdownHeadingLevel | null): TextChange | null {
  const parts = parseLine(line.text);
  const from = line.from + parts.lead.length + parts.list.length + parts.task.length;
  const insert = headingMarker(level);
  return insert === parts.heading ? null : { from, to: from + parts.heading.length, insert };
}

function setextChanges(state: EditorState, node: SyntaxNode, level: MarkdownHeadingLevel | null): TextChange[] {
  const underline = node.getChild("HeaderMark");
  if (!underline) return [];
  const underlineLine = state.doc.lineAt(underline.from);
  const content = linesBetween(state, node.from, underlineLine.from - 1);
  const changes: TextChange[] = [{ from: underlineLine.from - 1, to: underlineLine.to, insert: "" }];
  const [first, ...rest] = content;
  if (!level || !first) return changes;
  const marker = atxChange(first, level);
  if (marker) changes.push(marker);
  let previous = first;
  for (const line of rest) {
    changes.push({ from: previous.to, to: line.from + parseLine(line.text).lead.length, insert: " " });
    previous = line;
  }
  return changes;
}

function setextAt(state: EditorState, pos: number): SyntaxNode | null {
  for (let node: SyntaxNode | null = syntaxTree(state).resolveInner(pos, 1); node; node = node.parent) {
    if (node.name.startsWith("SetextHeading")) return node;
  }
  return null;
}

function headingChanges(state: EditorState, level: MarkdownHeadingLevel | null): TextChange[] {
  const changes: TextChange[] = [];
  const setexts = new Set<number>();
  for (const line of contentLines(touchedLines(state))) {
    if (codeBlockAt(state, line.from)) continue;
    const setext = setextAt(state, line.from);
    if (!setext) {
      const change = atxChange(line, level);
      if (change) changes.push(change);
    } else if (!setexts.has(setext.from)) {
      setexts.add(setext.from);
      changes.push(...setextChanges(state, setext, level));
    }
  }
  return changes;
}

export function setHeading(level: MarkdownHeadingLevel | null): StateCommand {
  return ({ state, dispatch }) => {
    if (state.readOnly) return false;
    if (codeBlockAt(state, state.selection.main.head)) return true;
    return dispatchChanges(state, dispatch, headingChanges(state, level));
  };
}

function blockPrefixFor(block: MarkdownBlockCommand): string {
  switch (block.type) {
    case "heading":
      return headingMarker(block.level);
    case "bulletList":
      return "- ";
    case "orderedList":
      return "1. ";
    case "taskList":
      return "- [ ] ";
    case "blockquote":
      return "> ";
    default:
      return "";
  }
}

type SlashResult = { insert: string; caret: number };

function standaloneBlock(state: EditorState, line: Line, content: string, block: string): SlashResult {
  const previous = line.number > 1 ? state.doc.line(line.number - 1) : null;
  const next = line.number < state.doc.lines ? state.doc.line(line.number + 1) : null;
  const separated = previous && !isBlank(previous) ? "\n" : "";
  const before = content.trim() ? `${content}\n\n` : separated;
  const after = next && !isBlank(next) ? "\n" : "";
  return { insert: `${before}${block}${after}`, caret: before.length };
}

function slashResult(state: EditorState, line: Line, content: string, caret: number, block: MarkdownBlockCommand): SlashResult {
  if (block.type === "codeBlock") return { insert: `${fence}\n${content}\n${fence}`, caret: fence.length + 1 + content.length };
  if (block.type === "horizontalRule") {
    const rule = standaloneBlock(state, line, content, "---\n");
    return { insert: rule.insert, caret: rule.caret + 4 };
  }
  if (block.type === "table") {
    const table = standaloneBlock(state, line, content, tableTemplate);
    return { insert: table.insert, caret: table.caret + 2 };
  }
  const prefix = blockPrefixFor(block);
  return { insert: prefix + content, caret: prefix.length + caret };
}

export function replaceWithBlock(range: MarkdownTextRange, block: MarkdownBlockCommand): StateCommand {
  return ({ state, dispatch }) => {
    if (state.readOnly) return false;
    const line = state.doc.lineAt(range.from);
    const start = range.from - line.from;
    const text = line.text.slice(0, start) + line.text.slice(Math.min(range.to, line.to) - line.from);
    const parts = parseLine(text);
    const stripped = text.length - parts.rest.length;
    const result = slashResult(state, line, parts.rest, Math.max(0, start - stripped), block);
    if (dispatch) {
      dispatch(
        state.update({
          changes: { from: line.from, to: line.to, insert: result.insert },
          selection: EditorSelection.cursor(line.from + result.caret),
          scrollIntoView: true,
          userEvent: "input.type",
        }),
      );
    }
    return true;
  };
}

import { syntaxTree } from "@codemirror/language";
import { type ChangeSpec, EditorSelection, type EditorState, type SelectionRange, type StateCommand } from "@codemirror/state";
import type { SyntaxNode } from "@lezer/common";
import type { MarkdownMark } from "../../engine";

export type TextChange = { from: number; to: number; insert: string };
type Span = { from: number; to: number };
type InlineFormat = { node: string; marker: string };

const formats: Record<MarkdownMark, InlineFormat> = {
  bold: { node: "StrongEmphasis", marker: "**" },
  italic: { node: "Emphasis", marker: "*" },
  strike: { node: "Strikethrough", marker: "~~" },
  code: { node: "InlineCode", marker: "`" },
};

/** Quote, list, task and heading markers that open a line before its text. */
export const blockPrefix = /^\s*(?:(?:[-*+]|\d+[.)])\s+(?:\[[ xX]\]\s+)?|>\s?|#{1,6}\s+)*/;
const codeBlockName = /^(?:FencedCode|CodeBlock)$/;
const proseBlockName = /^(?:Paragraph|ATXHeading\d|SetextHeading\d|Task|TableCell)$/;
const sides: readonly (-1 | 1)[] = [1, -1];
const boldItalicRun = 3;

export function enclosingNode(state: EditorState, span: Span, name: string): SyntaxNode | null {
  const tree = syntaxTree(state);
  for (const side of sides) {
    for (let node: SyntaxNode | null = tree.resolveInner(span.from, side); node; node = node.parent) {
      if (node.name === name && node.from <= span.from && node.to >= span.to) return node;
    }
  }
  return null;
}

function closest(node: SyntaxNode, pattern: RegExp): SyntaxNode | null {
  for (let current: SyntaxNode | null = node; current; current = current.parent) {
    if (pattern.test(current.name)) return current;
  }
  return null;
}

export function codeBlockAt(state: EditorState, pos: number): SyntaxNode | null {
  for (const side of sides) {
    const block = closest(syntaxTree(state).resolveInner(pos, side), codeBlockName);
    if (block) return block;
  }
  return null;
}

export function insideCode(state: EditorState, pos: number): boolean {
  if (codeBlockAt(state, pos)) return true;
  const span = enclosingNode(state, { from: pos, to: pos }, "InlineCode");
  return span !== null && span.from < pos && pos < span.to;
}

function holdsProse(state: EditorState, span: Span): boolean {
  const node = syntaxTree(state).resolveInner(span.from, 1);
  if (node.name === "HeaderMark") return false;
  const block = closest(node, proseBlockName);
  return block !== null && span.to <= block.to;
}

function textSegments(state: EditorState, range: SelectionRange): Span[] {
  const segments: Span[] = [];
  for (let pos = range.from; pos <= range.to; ) {
    const line = state.doc.lineAt(pos);
    const prefixEnd = line.from + (blockPrefix.exec(line.text)?.[0].length ?? 0);
    const from = Math.max(range.from, prefixEnd);
    const to = Math.min(range.to, line.to);
    const text = state.sliceDoc(from, to);
    const segment = { from: from + text.length - text.trimStart().length, to: to - (text.length - text.trimEnd().length) };
    if (segment.from < segment.to && holdsProse(state, segment)) segments.push(segment);
    pos = line.to + 1;
  }
  return segments;
}

function formattedAtCaret(state: EditorState, pos: number, format: InlineFormat): SyntaxNode | null {
  const node = enclosingNode(state, { from: pos, to: pos }, format.node);
  if (!node?.firstChild || !node.lastChild) return null;
  return pos >= node.firstChild.to && pos <= node.lastChild.from ? node : null;
}

function rangeIsFormatted(state: EditorState, range: SelectionRange, format: InlineFormat): boolean {
  if (range.empty) return formattedAtCaret(state, range.from, format) !== null;
  const segments = textSegments(state, range);
  return segments.length > 0 && segments.every((segment) => enclosingNode(state, segment, format.node));
}

export function isMarkActive(state: EditorState, mark: MarkdownMark): boolean {
  return state.selection.ranges.every((range) => rangeIsFormatted(state, range, formats[mark]));
}

function markerChanges(node: SyntaxNode): ChangeSpec[] {
  if (!node.firstChild || !node.lastChild) return [];
  return [
    { from: node.from, to: node.firstChild.to },
    { from: node.lastChild.from, to: node.to },
  ];
}

function nodesWithin(state: EditorState, span: Span, name: string): SyntaxNode[] {
  const nodes: SyntaxNode[] = [];
  syntaxTree(state).iterate({
    from: span.from,
    to: span.to,
    enter: (ref) => {
      if (ref.name === name && ref.to > span.from && ref.from < span.to) nodes.push(ref.node);
    },
  });
  return nodes;
}

export function mapInward(state: EditorState, specs: ChangeSpec[], range: SelectionRange) {
  const changes = state.changes(specs);
  const from = changes.mapPos(range.from, 1);
  const to = Math.max(from, changes.mapPos(range.to, -1));
  return { changes, range: range.anchor === range.from ? EditorSelection.range(from, to) : EditorSelection.range(to, from) };
}

function markerRuns(state: EditorState, pos: number, char: string) {
  const line = state.doc.lineAt(pos);
  const offset = pos - line.from;
  let before = 0;
  while (line.text.charAt(offset - before - 1) === char) before++;
  let after = 0;
  while (line.text.charAt(offset + after) === char) after++;
  return { before, after };
}

function toggleAtCaret(state: EditorState, range: SelectionRange, format: InlineFormat, formatted: boolean) {
  const pos = range.from;
  if (codeBlockAt(state, pos)) return { range };
  const node = formatted ? formattedAtCaret(state, pos, format) : null;
  if (node?.lastChild && pos === node.lastChild.from) return { range: EditorSelection.cursor(node.to) };
  if (node) return mapInward(state, markerChanges(node), range);
  const { marker } = format;
  const { before, after } = markerRuns(state, pos, marker.charAt(0));
  const emptyPair = before === after && (before === marker.length || (marker === "*" && before === boldItalicRun));
  if (emptyPair) {
    return { changes: { from: pos - marker.length, to: pos + marker.length }, range: EditorSelection.cursor(pos - marker.length) };
  }
  return { changes: { from: pos, insert: marker + marker }, range: EditorSelection.cursor(pos + marker.length) };
}

function toggleSegments(state: EditorState, range: SelectionRange, format: InlineFormat, formatted: boolean) {
  const specs: ChangeSpec[] = [];
  for (const segment of textSegments(state, range)) {
    if (formatted) {
      const node = enclosingNode(state, segment, format.node);
      if (node) specs.push(...markerChanges(node));
      continue;
    }
    const overlapping = nodesWithin(state, segment, format.node);
    const from = Math.min(segment.from, ...overlapping.map((node) => node.from));
    const to = Math.max(segment.to, ...overlapping.map((node) => node.to));
    specs.push(...overlapping.flatMap(markerChanges), { from, insert: format.marker }, { from: to, insert: format.marker });
  }
  return mapInward(state, specs, range);
}

export function toggleMark(mark: MarkdownMark): StateCommand {
  const format = formats[mark];
  return ({ state, dispatch }) => {
    if (state.readOnly) return false;
    const formatted = isMarkActive(state, mark);
    const update = state.changeByRange((range) =>
      range.empty ? toggleAtCaret(state, range, format, formatted) : toggleSegments(state, range, format, formatted),
    );
    dispatch(state.update(update, { scrollIntoView: true, userEvent: "input.format" }));
    return true;
  };
}

import { defaultKeymap } from "@codemirror/commands";
import { type Extension, Prec } from "@codemirror/state";
import { type KeyBinding, keymap } from "@codemirror/view";
import { markdownHeadingLevels } from "../../engine";
import { setHeading, toggleBlock } from "./blocks";
import { toggleMark } from "./inline";

/** CodeMirror's defaults, minus Mod-Enter: hosts use it to send what was written. */
export const editingKeymap: Extension = keymap.of(defaultKeymap.filter((binding) => binding.key !== "Mod-Enter"));

const markBindings: readonly KeyBinding[] = [
  { key: "Mod-b", run: toggleMark("bold") },
  { key: "Mod-i", run: toggleMark("italic") },
  { key: "Mod-Shift-s", run: toggleMark("strike") },
  { key: "Mod-e", run: toggleMark("code") },
];

export const markdownMarkKeymap: Extension = Prec.high(keymap.of(markBindings));

export const markdownFormatKeymap: Extension = Prec.high(
  keymap.of([
    ...markBindings,
    { key: "Mod-Alt-0", run: setHeading(null) },
    ...markdownHeadingLevels.map((level) => ({ key: `Mod-Alt-${level}`, run: setHeading(level) })),
    { key: "Mod-Shift-7", run: toggleBlock("orderedList") },
    { key: "Mod-Shift-8", run: toggleBlock("bulletList") },
    { key: "Mod-Shift-9", run: toggleBlock("taskList") },
    { key: "Mod-Shift-b", run: toggleBlock("blockquote") },
    { key: "Mod-Alt-c", run: toggleBlock("codeBlock") },
  ]),
);

import { EditorSelection, type EditorState, type SelectionRange, type StateCommand } from "@codemirror/state";
import type { SyntaxNode } from "@lezer/common";
import type { MarkdownMention, MarkdownTextRange } from "../../engine";
import { enclosingNode, insideCode, mapInward } from "./inline";

type LinkNode = { link: SyntaxNode; url: SyntaxNode };

const escapeText = (text: string) => text.replace(/[[\]\\]/g, "\\$&");

function escapeUrl(href: string): string {
  if (/\s/.test(href)) return `<${href.replace(/[<>]/g, "\\$&")}>`;
  return href.replace(/[()<>]/g, "\\$&");
}

function unescapeUrl(url: string): string {
  const bare = url.startsWith("<") && url.endsWith(">") ? url.slice(1, -1) : url;
  return bare.replace(/\\([!-/:-@[-`{-~])/g, "$1");
}

function linkAround(state: EditorState, range: SelectionRange): LinkNode | null {
  const link = enclosingNode(state, range, "Link");
  const url = link?.getChild("URL");
  return link && url ? { link, url } : null;
}

export function linkAt(state: EditorState): { from: number; to: number; href: string } | null {
  const found = linkAround(state, state.selection.main);
  if (!found) return null;
  return { from: found.link.from, to: found.link.to, href: unescapeUrl(state.sliceDoc(found.url.from, found.url.to)) };
}

function unlink(state: EditorState, range: SelectionRange) {
  const found = linkAround(state, range);
  const [open, close] = found?.link.getChildren("LinkMark") ?? [];
  if (!found || !open || !close) return { range };
  return mapInward(
    state,
    [
      { from: found.link.from, to: open.to },
      { from: close.from, to: found.link.to },
    ],
    range,
  );
}

function linkRange(state: EditorState, range: SelectionRange, href: string) {
  const found = linkAround(state, range);
  const url = escapeUrl(href);
  if (found) return { changes: { from: found.url.from, to: found.url.to, insert: url }, range };
  if (insideCode(state, range.from)) return { range };
  if (range.empty) {
    const insert = `[${escapeText(href)}](${url})`;
    return { changes: { from: range.from, insert }, range: EditorSelection.cursor(range.from + insert.length) };
  }
  return {
    changes: [
      { from: range.from, insert: "[" },
      { from: range.to, insert: `](${url})` },
    ],
    range: EditorSelection.range(range.anchor + 1, range.head + 1),
  };
}

export function setLink(href: string | null): StateCommand {
  return ({ state, dispatch }) => {
    if (state.readOnly) return false;
    const target = href?.trim() ? href.trim() : null;
    const update = state.changeByRange((range) => (target ? linkRange(state, range, target) : unlink(state, range)));
    dispatch(state.update(update, { scrollIntoView: true, userEvent: "input.format" }));
    return true;
  };
}

export function imageMarkdown(image: { src: string; alt: string; title?: string }): string {
  const title = image.title ? ` "${image.title.replace(/["\\]/g, "\\$&")}"` : "";
  return `![${escapeText(image.alt)}](${escapeUrl(image.src)}${title})`;
}

export function insertImage(image: { src: string; alt: string }): StateCommand {
  return ({ state, dispatch }) => {
    if (state.readOnly) return false;
    const insert = imageMarkdown(image);
    const update = state.changeByRange((range) => ({
      changes: { from: range.from, to: range.to, insert },
      range: EditorSelection.cursor(range.from + insert.length),
    }));
    dispatch(state.update(update, { scrollIntoView: true, userEvent: "input.format" }));
    return true;
  };
}

export function replaceWithMention(range: MarkdownTextRange, mention: MarkdownMention): StateCommand {
  return ({ state, dispatch }) => {
    if (state.readOnly) return false;
    const insert = `[@${escapeText(mention.label)}](${escapeUrl(mention.href)}) `;
    dispatch(
      state.update({
        changes: { from: range.from, to: range.to, insert },
        selection: EditorSelection.cursor(range.from + insert.length),
        scrollIntoView: true,
        userEvent: "input.type",
      }),
    );
    return true;
  };
}

import type { ChangeSpec, StateCommand, Text } from "@codemirror/state";

type ListItem = { indent: number; content: number };

const listItemPattern = /^([ \t]*)(?:[-*+]|\d{1,9}[.)])[ \t]/;
const indentOf = (text: string) => text.length - text.trimStart().length;

function listItemAt(doc: Text, number: number): ListItem | null {
  const match = listItemPattern.exec(doc.line(number).text);
  return match ? { indent: match[1]?.length ?? 0, content: match[0].length } : null;
}

/** The nearest earlier item the predicate accepts, searching only within the same list. */
function earlierItem(doc: Text, number: number, accept: (item: ListItem) => boolean | null): ListItem | null {
  for (let previous = number - 1; previous >= 1; previous--) {
    const text = doc.line(previous).text;
    if (text.trim() === "") continue;
    const item = listItemAt(doc, previous);
    if (!item) {
      if (indentOf(text) === 0) return null;
      continue;
    }
    const verdict = accept(item);
    if (verdict !== false) return verdict ? item : null;
  }
  return null;
}

function lastNestedLine(doc: Text, number: number, indent: number) {
  let last = number;
  for (let next = number + 1; next <= doc.lines; next++) {
    const text = doc.line(next).text;
    if (text.trim() === "") continue;
    if (indentOf(text) <= indent) break;
    last = next;
  }
  return last;
}

function shiftLines(doc: Text, first: number, last: number, delta: number): ChangeSpec[] {
  const changes: ChangeSpec[] = [];
  for (let number = first; number <= last; number++) {
    const line = doc.line(number);
    if (line.text.trim() === "") continue;
    if (delta > 0) changes.push({ from: line.from, insert: " ".repeat(delta) });
    else changes.push({ from: line.from, to: line.from + Math.min(-delta, indentOf(line.text)) });
  }
  return changes;
}

/** Tab nests a list item under the one before it; Shift-Tab moves it out one level. Otherwise Tab keeps moving focus. */
export function indentListItem(direction: 1 | -1): StateCommand {
  return ({ state, dispatch }) => {
    const { doc } = state;
    const number = doc.lineAt(state.selection.main.head).number;
    const item = listItemAt(doc, number);
    if (!item) return false;
    const target =
      direction > 0
        ? earlierItem(doc, number, (candidate) => (candidate.indent < item.indent ? null : candidate.indent === item.indent))?.content
        : earlierItem(doc, number, (candidate) => candidate.indent < item.indent)?.indent;
    if (target === undefined) return false;
    const changes = shiftLines(doc, number, lastNestedLine(doc, number, item.indent), target - item.indent);
    dispatch(state.update({ changes, scrollIntoView: true, userEvent: direction > 0 ? "input.indent" : "delete.dedent" }));
    return true;
  };
}

import { redo, redoDepth, undo, undoDepth } from "@codemirror/commands";
import { EditorSelection, EditorState, type StateCommand } from "@codemirror/state";
import { EditorView } from "@codemirror/view";
import type { MarkdownEditorEngine, MarkdownEditorSnapshot, MarkdownTextBeforeCaret } from "../engine";
import { createLiveBlocks } from "./drag/block-drag";
import { activeBlocks, headingLevel, replaceWithBlock, setHeading, toggleBlock } from "./format/blocks";
import { blockPrefix, codeBlockAt, enclosingNode, insideCode, isMarkActive, toggleMark } from "./format/inline";
import { insertImage, linkAt, replaceWithMention, setLink } from "./format/links";
import { type LiveServices, type LiveSettings, liveSetup, reconfigureLive } from "./live-setup";
import { activeTableCell, createLiveTables } from "./table/live-tables";
import { createLiveUploads } from "./upload-placeholders";

export type LiveEditor = {
  readonly engine: MarkdownEditorEngine;
  readonly view: EditorView;
  configure: (settings: Partial<Omit<LiveSettings, "editable">>) => void;
  focusEnd: () => void;
  destroy: () => void;
};

function readSnapshot(state: EditorState, focused: boolean, isEmpty: boolean): MarkdownEditorSnapshot {
  const { main } = state.selection;
  return {
    marks: {
      bold: isMarkActive(state, "bold"),
      italic: isMarkActive(state, "italic"),
      strike: isMarkActive(state, "strike"),
      code: isMarkActive(state, "code"),
    },
    blocks: activeBlocks(state),
    heading: headingLevel(state),
    link: linkAt(state)?.href ?? null,
    canUndo: undoDepth(state) > 0,
    canRedo: redoDepth(state) > 0,
    focused,
    formattable: !main.empty && state.sliceDoc(main.from, main.to).trim() !== "" && codeBlockAt(state, main.from) === null,
    inlineOnly: enclosingNode(state, main, "Table") !== null,
    isEmpty,
    sourceRequired: false,
  };
}

/** Text from the start of the caret's block to the caret, in outer document positions. */
function textBefore(state: EditorState, offset: number): MarkdownTextBeforeCaret | null {
  const { main } = state.selection;
  if (!main.empty || insideCode(state, main.head) || linkAt(state)) return null;
  const line = state.doc.lineAt(main.head);
  const start = line.from + (blockPrefix.exec(line.text)?.[0].length ?? 0);
  if (main.head < start) return null;
  return { text: state.sliceDoc(start, main.head), from: offset + start, to: offset + main.head };
}

function rectBetween(view: EditorView, from: number, to: number): DOMRect | null {
  const start = view.coordsAtPos(from, 1);
  const end = to === from ? start : view.coordsAtPos(to, -1);
  if (!(start && end)) return null;
  const left = Math.min(start.left, end.left);
  return new DOMRect(left, start.top, Math.max(start.right, end.right) - left, end.bottom - start.top);
}

export function createLiveEditor(markdown: string, editable: boolean, services: Omit<LiveServices, "onUpdate">): LiveEditor {
  const listeners = new Set<() => void>();
  const changeListeners = new Set<(markdown: string) => void>();
  let current = markdown;
  let settings: LiveSettings = { editable, preview: true, attributes: { role: "textbox", "aria-multiline": "true" }, placeholder: "" };
  const notify = () => {
    for (const listener of listeners) listener();
  };
  const onUpdate = EditorView.updateListener.of((update) => {
    if (update.docChanged) {
      current = update.state.doc.toString();
      for (const listener of changeListeners) listener(current);
    }
    notify();
  });
  const createState = (doc: string) => EditorState.create({ doc, extensions: liveSetup(settings, { ...services, onUpdate }) });
  const view = new EditorView({ state: createState(markdown) });
  const notifyFocus = () => queueMicrotask(notify);
  view.contentDOM.addEventListener("focusin", notifyFocus);
  view.contentDOM.addEventListener("focusout", notifyFocus);

  let emptiness = { doc: view.state.doc, isEmpty: markdown.trim() === "" };
  let cache: { state: EditorState; focused: boolean; snapshot: MarkdownEditorSnapshot } | null = null;
  const focusedCell = () => activeTableCell(view);
  const caretView = () => focusedCell()?.editor ?? view;
  const run = (command: StateCommand) => {
    if (!focusedCell()) view.focus();
    command({ state: view.state, dispatch: (transaction) => view.dispatch(transaction) });
  };

  function configure(next: Partial<LiveSettings>) {
    const merged = { ...settings, ...next };
    const effects = reconfigureLive(settings, merged);
    settings = merged;
    if (effects.length > 0) view.dispatch({ effects });
  }

  const engine: MarkdownEditorEngine = {
    element: view.contentDOM,
    sourceView: "editor",
    subscribe(listener) {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
    getSnapshot() {
      const { state } = view;
      const focused = view.contentDOM.contains(view.root.activeElement);
      if (cache?.state === state && cache.focused === focused) return cache.snapshot;
      if (emptiness.doc !== state.doc) emptiness = { doc: state.doc, isEmpty: state.sliceDoc().trim() === "" };
      cache = { state, focused, snapshot: readSnapshot(state, focused, emptiness.isEmpty) };
      return cache.snapshot;
    },
    onChange(listener) {
      changeListeners.add(listener);
      return () => {
        changeListeners.delete(listener);
      };
    },
    getMarkdown: () => current,
    setMarkdown(next) {
      if (next === current) return;
      current = next;
      view.setState(createState(next));
      notify();
    },
    setEditable: (next) => configure({ editable: next }),
    focus: () => view.focus(),
    undo: () => run(undo),
    redo: () => run(redo),
    toggleMark: (mark) => run(toggleMark(mark)),
    toggleBlock: (block) => run(toggleBlock(block)),
    setHeading: (level) => run(setHeading(level)),
    setLink: (href) => run(setLink(href)),
    insertImage: (image) => run(insertImage(image)),
    selectionRect() {
      const target = caretView();
      const { from, to } = target.state.selection.main;
      return rectBetween(target, from, to);
    },
    textBeforeCaret() {
      const cell = focusedCell();
      if (cell) return textBefore(cell.editor.state, cell.from);
      return view.hasFocus ? textBefore(view.state, 0) : null;
    },
    caretRect() {
      const target = caretView();
      const { head } = target.state.selection.main;
      return rectBetween(target, head, head);
    },
    replaceWithBlock: (range, block) => run(replaceWithBlock(range, block)),
    replaceWithMention: (range, mention) => run(replaceWithMention(range, mention)),
    positionAt: (point) => view.posAtCoords(point),
    uploads: createLiveUploads(view),
    blocks: createLiveBlocks(view),
    tables: createLiveTables(view),
  };

  return {
    engine,
    view,
    configure,
    focusEnd() {
      view.dispatch({ selection: EditorSelection.cursor(view.state.doc.length), scrollIntoView: true });
      view.focus();
    },
    destroy() {
      view.contentDOM.removeEventListener("focusin", notifyFocus);
      view.contentDOM.removeEventListener("focusout", notifyFocus);
      view.destroy();
    },
  };
}

import { history, historyKeymap } from "@codemirror/commands";
import { markdownKeymap, markdownLanguage, pasteURLAsLink } from "@codemirror/lang-markdown";
import { Compartment, EditorState, type Extension, Prec, type StateCommand, type StateEffect } from "@codemirror/state";
import { EditorView, keymap, placeholder } from "@codemirror/view";
import type { MarkdownUrlPolicy } from "../url-policy";
import { blockDragging } from "./drag/block-drag";
import { insideCode } from "./format/inline";
import { editingKeymap, markdownFormatKeymap } from "./format/keymap";
import { indentListItem } from "./format/list-indent";
import { livePreview, markdownUrlPolicy } from "./preview/live-preview";
import { recipeTheme } from "./preview/recipe-theme";
import { type TaskCheckboxes, taskCheckboxes } from "./preview/widgets";
import { liveTables } from "./table/live-tables";
import { uploadPlaceholders } from "./upload-placeholders";

/** `preview` off shows the Markdown source in the same editor. */
export type LiveSettings = {
  editable: boolean;
  preview: boolean;
  attributes: Record<string, string>;
  placeholder: string;
};

export type LiveServices = {
  isUrlAllowed: MarkdownUrlPolicy;
  tasks: TaskCheckboxes;
  onUpdate: Extension;
};

const editableSetting = new Compartment();
const previewSetting = new Compartment();
const contentSetting = new Compartment();

const editability = (editable: boolean) => [EditorView.editable.of(editable), EditorState.readOnly.of(!editable)];
const previewing = (preview: boolean) => (preview ? [livePreview, liveTables] : []);
const describing = ({ attributes, placeholder: text }: LiveSettings) => [
  EditorView.contentAttributes.of(attributes),
  text ? placeholder(text) : [],
];

/** Enter ends a paragraph or heading with a blank line, as a rich editor starts a new paragraph. */
const paragraphBreak: StateCommand = ({ state, dispatch }) => {
  const { main } = state.selection;
  if (state.selection.ranges.length > 1 || state.doc.lineAt(main.head).text.trim() === "" || insideCode(state, main.head)) return false;
  dispatch(state.update(state.replaceSelection("\n\n"), { scrollIntoView: true, userEvent: "input" }));
  return true;
};

const structureKeymap = Prec.high(
  keymap.of([
    ...markdownKeymap,
    { key: "Enter", run: paragraphBreak },
    { key: "Tab", run: indentListItem(1) },
    { key: "Shift-Tab", run: indentListItem(-1) },
  ]),
);

export function liveSetup(settings: LiveSettings, services: LiveServices): Extension {
  return [
    markdownLanguage.extension,
    pasteURLAsLink,
    history(),
    structureKeymap,
    markdownFormatKeymap,
    keymap.of(historyKeymap),
    editingKeymap,
    recipeTheme,
    EditorView.lineWrapping,
    blockDragging,
    uploadPlaceholders,
    markdownUrlPolicy.of(services.isUrlAllowed),
    taskCheckboxes.of(services.tasks),
    services.onUpdate,
    editableSetting.of(editability(settings.editable)),
    previewSetting.of(previewing(settings.preview)),
    contentSetting.of(describing(settings)),
  ];
}

export function reconfigureLive(previous: LiveSettings, next: LiveSettings): StateEffect<unknown>[] {
  const effects: StateEffect<unknown>[] = [];
  if (previous.editable !== next.editable) effects.push(editableSetting.reconfigure(editability(next.editable)));
  if (previous.preview !== next.preview) effects.push(previewSetting.reconfigure(previewing(next.preview)));
  if (previous.attributes !== next.attributes || previous.placeholder !== next.placeholder) {
    effects.push(contentSetting.reconfigure(describing(next)));
  }
  return effects;
}

import { syntaxTree } from "@codemirror/language";
import { type EditorState, Facet, type Range, type SelectionRange } from "@codemirror/state";
import { Decoration, type DecorationSet, type EditorView, ViewPlugin, type ViewUpdate } from "@codemirror/view";
import type { SyntaxNode } from "@lezer/common";
import { markdownHeadingAttributes } from "@/components/control-ui/ui/markdown-heading";
import { markdownHeadingLevels } from "../../engine";
import { type MarkdownUrlPolicy, persistentUrlPolicy } from "../../url-policy";
import { BulletWidget, ImageWidget, TaskWidget } from "./widgets";

type Span = { from: number; to: number };
type Preview = {
  state: EditorState;
  selection: readonly SelectionRange[];
  visible: Span;
  decorations: Range<Decoration>[];
  codeSpans: Span[];
};
/** Returning false skips the node's children. */
type Decorate = (preview: Preview, node: SyntaxNode) => false | undefined;

export const markdownUrlPolicy = Facet.define<MarkdownUrlPolicy, MarkdownUrlPolicy>({
  combine: (policies) => policies[0] ?? persistentUrlPolicy,
});

const hidden = Decoration.replace({});
const bullet = Decoration.replace({ widget: new BulletWidget() });
const link = Decoration.mark({ tagName: "a" });
const lineClasses = new Map<string, Decoration>();

function lineClass(className: string) {
  let decoration = lineClasses.get(className);
  if (!decoration) {
    decoration = Decoration.line({ class: className });
    lineClasses.set(className, decoration);
  }
  return decoration;
}

/** Inline markup shows while the selection touches its span, edges included. */
const touches = (selection: readonly SelectionRange[], span: Span) =>
  selection.some((range) => range.from <= span.to && range.to >= span.from);

/** A block prefix shows while the selection is inside it; a caret right after it, where the text starts, keeps it rendered. */
const insidePrefix = (selection: readonly SelectionRange[], span: Span) =>
  selection.some((range) => range.from < span.to && range.to >= span.from);

const leadingBlanks = (text: string) => text.length - text.trimStart().length;
const lineOf = (preview: Preview, pos: number) => preview.state.doc.lineAt(pos);

function hide(preview: Preview, span: Span, decoration = hidden) {
  if (span.from < span.to) preview.decorations.push(decoration.range(span.from, span.to));
}

function decorateLines(preview: Preview, block: Span, className: string) {
  const { doc } = preview.state;
  const first = doc.lineAt(Math.max(block.from, preview.visible.from));
  const last = doc.lineAt(Math.min(block.to, preview.visible.to));
  for (let number = first.number; number <= last.number; number++) {
    preview.decorations.push(lineClass(className).range(doc.line(number).from));
  }
}

const decorateCode: Decorate = (preview, node) => {
  const { state, selection } = preview;
  preview.codeSpans.push(node);
  decorateLines(preview, node, "cm-md-code-line");
  preview.decorations.push(lineClass("cm-md-code-start").range(lineOf(preview, node.from).from));
  preview.decorations.push(lineClass("cm-md-code-end").range(lineOf(preview, node.to).from));
  if (node.name === "FencedCode" && !touches(selection, node)) {
    for (const fence of node.getChildren("CodeMark")) {
      const line = state.doc.lineAt(fence.from);
      hide(preview, line);
      preview.decorations.push(lineClass("cm-md-fence").range(line.from));
    }
  }
  return false;
};

function headingLine(level: number) {
  const heading = markdownHeadingLevels.find((candidate) => candidate === level);
  return heading
    ? Decoration.line({ class: markdownHeadingAttributes(heading).class, attributes: { "data-heading": String(heading) } })
    : null;
}

function decorateHeading(level: number, setext: boolean): Decorate {
  const decoration = headingLine(level);
  return (preview, node) => {
    const { doc } = preview.state;
    const first = doc.lineAt(node.from).number;
    const last = setext ? doc.lineAt(node.to).number - 1 : first;
    for (let number = first; number <= last; number++) {
      if (decoration) preview.decorations.push(decoration.range(doc.line(number).from));
    }
    return undefined;
  };
}

const decorateHeaderMark: Decorate = (preview, node) => {
  const { state, selection } = preview;
  const heading = node.parent;
  const line = lineOf(preview, node.from);
  if (!heading?.name.startsWith("ATXHeading")) {
    if (!touches(selection, line)) hide(preview, line);
    return undefined;
  }
  if (node.from === heading.from) {
    const span = { from: node.from, to: node.to + leadingBlanks(state.sliceDoc(node.to, line.to)) };
    if (!insidePrefix(selection, { from: line.from, to: span.to })) hide(preview, span);
    return undefined;
  }
  const before = state.sliceDoc(line.from, node.from);
  const span = { from: node.from - (before.length - before.trimEnd().length), to: node.to };
  if (!touches(selection, span)) hide(preview, span);
  return undefined;
};

const decorateQuoteMark: Decorate = (preview, node) => {
  const line = lineOf(preview, node.from);
  const span = { from: node.from, to: node.to + Math.min(1, leadingBlanks(preview.state.sliceDoc(node.to, line.to))) };
  if (!insidePrefix(preview.selection, span)) hide(preview, span);
  return undefined;
};

const decorateListMark: Decorate = (preview, node) => {
  const item = node.parent;
  if (item?.parent?.name !== "BulletList") return undefined;
  const task = item.getChild("Task")?.getChild("TaskMarker");
  if (insidePrefix(preview.selection, { from: node.from, to: (task ?? node).to + 1 })) return undefined;
  if (task) hide(preview, { from: node.from, to: task.from });
  else hide(preview, node, bullet);
  return undefined;
};

const decorateTaskMarker: Decorate = (preview, node) => {
  const { state, selection } = preview;
  const line = lineOf(preview, node.from);
  if (insidePrefix(selection, { from: line.from, to: node.to + 1 })) return undefined;
  const checked = state.sliceDoc(node.from + 1, node.to - 1).toLowerCase() === "x";
  const label = state.sliceDoc(node.to, line.to).trim();
  hide(preview, node, Decoration.replace({ widget: new TaskWidget(checked, label) }));
  return undefined;
};

function inlineMark(tagName: string): Decorate {
  const decoration = Decoration.mark({ tagName });
  return (preview, node) => {
    preview.decorations.push(decoration.range(node.from, node.to));
    return undefined;
  };
}

const decorateInlineMarkup: Decorate = (preview, node) => {
  const owner = node.parent;
  if (owner && !touches(preview.selection, owner)) hide(preview, node);
  return undefined;
};

const decorateLink: Decorate = (preview, node) => {
  const [open, close] = node.getChildren("LinkMark");
  if (!(open && close && node.getChild("URL"))) return undefined;
  if (open.to < close.from) preview.decorations.push(link.range(open.to, close.from));
  if (touches(preview.selection, node)) return undefined;
  hide(preview, open);
  hide(preview, { from: close.from, to: node.to });
  return undefined;
};

const decorateAutolink: Decorate = (preview, node) => {
  const url = node.getChild("URL");
  if (url) preview.decorations.push(link.range(url.from, url.to));
  if (!touches(preview.selection, node)) for (const mark of node.getChildren("LinkMark")) hide(preview, mark);
  return false;
};

function imageDecoration(state: EditorState, image: SyntaxNode) {
  const [open, close] = image.getChildren("LinkMark");
  const url = image.getChild("URL");
  if (!(open && close && url)) return null;
  const raw = state.sliceDoc(url.from, url.to);
  const src = raw.startsWith("<") && raw.endsWith(">") ? raw.slice(1, -1) : raw;
  if (!state.facet(markdownUrlPolicy)(src, "image")) return null;
  const title = image.getChild("LinkTitle");
  const alt = state.sliceDoc(open.to, close.from);
  return Decoration.replace({ widget: new ImageWidget(src, alt, title ? state.sliceDoc(title.from + 1, title.to - 1) : "") });
}

const decorateImage: Decorate = (preview, node) => {
  const decoration = touches(preview.selection, node) ? null : imageDecoration(preview.state, node);
  if (decoration) hide(preview, node, decoration);
  return false;
};

const decorateRule: Decorate = (preview, node) => {
  const line = lineOf(preview, node.from);
  if (touches(preview.selection, line)) return undefined;
  hide(preview, node);
  preview.decorations.push(lineClass("cm-md-rule-line").range(line.from));
  return undefined;
};

const decorators: Record<string, Decorate> = {
  Table: () => false,
  FencedCode: decorateCode,
  CodeBlock: decorateCode,
  Blockquote: (preview, node) => {
    decorateLines(preview, node, "cm-md-quote-line");
    return undefined;
  },
  HorizontalRule: decorateRule,
  Image: decorateImage,
  Link: decorateLink,
  Autolink: decorateAutolink,
  URL: (preview, node) => {
    if (node.parent?.name === "Paragraph") preview.decorations.push(link.range(node.from, node.to));
    return undefined;
  },
  Escape: (preview, node) => {
    if (!touches(preview.selection, node)) hide(preview, { from: node.from, to: node.from + 1 });
    return undefined;
  },
  HeaderMark: decorateHeaderMark,
  QuoteMark: decorateQuoteMark,
  ListMark: decorateListMark,
  TaskMarker: decorateTaskMarker,
  Emphasis: inlineMark("em"),
  StrongEmphasis: inlineMark("strong"),
  Strikethrough: inlineMark("s"),
  InlineCode: inlineMark("code"),
  EmphasisMark: decorateInlineMarkup,
  StrikethroughMark: decorateInlineMarkup,
  CodeMark: decorateInlineMarkup,
  ...Object.fromEntries(markdownHeadingLevels.map((level) => [`ATXHeading${level}`, decorateHeading(level, false)])),
  SetextHeading1: decorateHeading(1, true),
  SetextHeading2: decorateHeading(2, true),
};

/** Blank lines between blocks shrink to the block gap, except the caret's line and lines inside code. */
function decorateBlankLines(preview: Preview) {
  const { doc, selection } = preview.state;
  if (doc.lines < 2) return;
  const caretLine = doc.lineAt(selection.main.head).number;
  for (let pos = preview.visible.from; pos <= preview.visible.to; ) {
    const line = doc.lineAt(pos);
    const inCode = preview.codeSpans.some((span) => span.from <= line.from && line.to <= span.to);
    if (line.number !== caretLine && !inCode && line.text.trim() === "")
      preview.decorations.push(lineClass("cm-md-blank").range(line.from));
    pos = line.to + 1;
  }
}

function previewDecorations(view: EditorView): DecorationSet {
  const decorations: Range<Decoration>[] = [];
  const selection = view.hasFocus ? view.state.selection.ranges : [];
  for (const visible of view.visibleRanges) {
    const preview: Preview = { state: view.state, selection, visible, decorations, codeSpans: [] };
    syntaxTree(view.state).iterate({
      from: visible.from,
      to: visible.to,
      enter: (ref) => decorators[ref.name]?.(preview, ref.node),
    });
    decorateBlankLines(preview);
  }
  return Decoration.set(decorations, true);
}

export const livePreview = ViewPlugin.fromClass(
  class {
    decorations: DecorationSet;

    constructor(view: EditorView) {
      this.decorations = previewDecorations(view);
    }

    update(update: ViewUpdate) {
      const treeChanged = syntaxTree(update.startState) !== syntaxTree(update.state);
      if (update.docChanged || update.selectionSet || update.focusChanged || update.viewportChanged || treeChanged) {
        this.decorations = previewDecorations(update.view);
      }
    }
  },
  { decorations: (plugin) => plugin.decorations },
);

import { EditorView } from "@codemirror/view";

/** CodeMirror's unlayered base styles beat every cascade layer; `revert-layer` hands each property back to the recipe. */
export const recipeTheme = EditorView.theme({
  "&.cm-focused": { outline: "revert-layer" },
  ".cm-scroller": { fontFamily: "revert-layer", lineHeight: "revert-layer", overflowX: "revert-layer" },
  ".cm-content": { padding: "revert-layer", caretColor: "revert-layer", minHeight: "revert-layer" },
  ".cm-line": { padding: "revert-layer" },
  ".cm-placeholder": { color: "revert-layer" },
});

"use client";

import { useSyncExternalStore } from "react";
import { createPortal } from "react-dom";
import { Checkbox } from "@/components/control-ui/ui/checkbox";
import { useMarkdownEditor } from "../../context";
import type { TaskCheckboxes } from "./widgets";

export function LiveTaskCheckboxes({ registry }: { registry: TaskCheckboxes }) {
  const entries = useSyncExternalStore(registry.subscribe, registry.getSnapshot, registry.getSnapshot);
  const { disabled, readOnly, labels } = useMarkdownEditor();
  return entries.map(({ host, key, checkbox }) =>
    createPortal(
      <Checkbox
        checked={checkbox.checked}
        disabled={disabled}
        readOnly={readOnly}
        aria-label={checkbox.label || labels.taskItem}
        onCheckedChange={(checked) => checkbox.toggle(checked)}
      />,
      host,
      key,
    ),
  );
}

import { isolateHistory } from "@codemirror/commands";
import { Facet } from "@codemirror/state";
import { type EditorView, WidgetType } from "@codemirror/view";

export type TaskCheckbox = { checked: boolean; label: string; toggle: (checked: boolean) => void };
export type TaskCheckboxEntry = { host: HTMLElement; key: string; checkbox: TaskCheckbox };

/** Task checkboxes render as React portals: each widget registers its host element, the editor content renders into it. */
export class TaskCheckboxes {
  private entries = new Map<HTMLElement, TaskCheckboxEntry>();
  private listeners = new Set<() => void>();
  private snapshot: readonly TaskCheckboxEntry[] = [];
  private nextKey = 0;

  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  };

  getSnapshot = () => this.snapshot;

  set(host: HTMLElement, checkbox: TaskCheckbox | null) {
    if (checkbox) this.entries.set(host, { host, key: this.entries.get(host)?.key ?? String(this.nextKey++), checkbox });
    else if (!this.entries.delete(host)) return;
    this.snapshot = Array.from(this.entries.values());
    for (const listener of this.listeners) listener();
  }
}

export const taskCheckboxes = Facet.define<TaskCheckboxes, TaskCheckboxes | null>({ combine: (values) => values[0] ?? null });

const registryOf = new WeakMap<HTMLElement, TaskCheckboxes>();

function toggleTask(view: EditorView, host: HTMLElement, checked: boolean) {
  if (view.state.readOnly || !host.isConnected) return;
  const from = view.posAtDOM(host);
  if (!/^\[[ xX]\]$/.test(view.state.sliceDoc(from, from + 3))) return;
  view.dispatch({
    changes: { from: from + 1, to: from + 2, insert: checked ? "x" : " " },
    annotations: isolateHistory.of("full"),
    userEvent: "input.toggle",
  });
}

export class TaskWidget extends WidgetType {
  constructor(
    readonly checked: boolean,
    readonly label: string,
  ) {
    super();
  }

  eq(other: TaskWidget) {
    return other.checked === this.checked && other.label === this.label;
  }

  toDOM(view: EditorView) {
    const host = document.createElement("span");
    host.dataset.controlUi = "markdown-editor";
    host.dataset.controlFamily = "markdown-editor";
    host.dataset.slot = "task-checkbox";
    this.register(view, host);
    return host;
  }

  updateDOM(host: HTMLElement, view: EditorView) {
    this.register(view, host);
    return true;
  }

  destroy(host: HTMLElement) {
    registryOf.get(host)?.set(host, null);
    registryOf.delete(host);
  }

  private register(view: EditorView, host: HTMLElement) {
    const registry = view.state.facet(taskCheckboxes);
    if (!registry) return;
    registryOf.set(host, registry);
    registry.set(host, { checked: this.checked, label: this.label, toggle: (checked) => toggleTask(view, host, checked) });
  }
}

export class BulletWidget extends WidgetType {
  eq() {
    return true;
  }

  toDOM() {
    const bullet = document.createElement("span");
    bullet.className = "cm-md-bullet";
    bullet.textContent = "•";
    bullet.setAttribute("aria-hidden", "true");
    return bullet;
  }
}

export class ImageWidget extends WidgetType {
  constructor(
    readonly src: string,
    readonly alt: string,
    readonly title: string,
  ) {
    super();
  }

  eq(other: ImageWidget) {
    return other.src === this.src && other.alt === this.alt && other.title === this.title;
  }

  toDOM() {
    const image = document.createElement("img");
    image.src = this.src;
    image.alt = this.alt;
    if (this.title) image.title = this.title;
    image.className = "cm-md-image";
    return image;
  }

  /** A click on the image puts the caret beside it, which reveals its Markdown. */
  ignoreEvent() {
    return false;
  }
}

import { redo, undo } from "@codemirror/commands";
import { defineLanguageFacet, Language, languageDataProp } from "@codemirror/language";
import {
  Annotation,
  type ChangeSet,
  Compartment,
  EditorSelection,
  EditorState,
  type Extension,
  Prec,
  type SelectionRange,
  Transaction,
} from "@codemirror/state";
import { EditorView, keymap } from "@codemirror/view";
import { GFM, parser } from "@lezer/markdown";
import { editingKeymap, markdownMarkKeymap } from "../format/keymap";
import { livePreview, markdownUrlPolicy } from "../preview/live-preview";
import { recipeTheme } from "../preview/recipe-theme";
import { escapeCellText } from "./table-model";

export type CellMove = "next" | "previous" | "below" | "up" | "down" | "left" | "right";
export type CellEdit = { changes: ChangeSet; selection: SelectionRange; userEvent: string | undefined };

export type CellHost = {
  readonly outer: EditorView;
  forward: (cell: CellEditor, edit: CellEdit) => void;
  navigate: (cell: CellEditor, move: CellMove) => boolean;
  columnHeaderId: (column: number) => string;
};

const cellData = defineLanguageFacet();
/** A table cell holds one line of inline Markdown, so every block syntax is left out of its parser. */
const cellLanguage = new Language(
  cellData,
  parser.configure([
    GFM,
    {
      remove: [
        "LinkReference",
        "IndentedCode",
        "FencedCode",
        "Blockquote",
        "HorizontalRule",
        "BulletList",
        "OrderedList",
        "ATXHeading",
        "HTMLBlock",
        "SetextHeading",
        "Table",
        "TaskList",
      ],
      props: [languageDataProp.add({ Document: cellData })],
    },
  ]),
  [],
  "markdown-cell",
);

const fromTable = Annotation.define<true>();

function oddBackslashesBefore(state: EditorState, pos: number) {
  let count = 0;
  while (pos - count > 0 && state.sliceDoc(pos - count - 1, pos - count) === "\\") count++;
  return count % 2 === 1;
}

/** A pipe would end the cell and a newline the row, so typed and pasted ones are escaped or flattened. */
const cellInput = EditorState.transactionFilter.of((transaction) => {
  if (!transaction.docChanged || transaction.annotation(fromTable)) return transaction;
  const { startState } = transaction;
  let rewritten = false;
  const changes: { from: number; to: number; insert: string }[] = [];
  transaction.changes.iterChanges((from, to, _fromB, _toB, inserted) => {
    const text = inserted.toString();
    const prefix = oddBackslashesBefore(startState, from) ? "\\" : "";
    const insert = escapeCellText(prefix + text).slice(prefix.length);
    rewritten ||= insert !== text;
    changes.push({ from, to, insert });
  });
  if (!rewritten) return transaction;
  const changeSet = startState.changes(changes);
  return {
    changes: changeSet,
    selection: EditorSelection.cursor(changeSet.mapPos(startState.selection.main.to, 1)),
    effects: transaction.effects,
    userEvent: transaction.annotation(Transaction.userEvent),
    scrollIntoView: transaction.scrollIntoView,
  };
});

function atVerticalEdge(view: EditorView, forward: boolean) {
  const range = view.state.selection.main;
  if (!range.empty) return false;
  const moved = view.moveVertically(range, forward);
  return moved.head === range.head || moved.head === (forward ? view.state.doc.length : 0);
}

function cellKeymap(cell: CellEditor) {
  const { host } = cell;
  const go = (move: CellMove) => () => host.navigate(cell, move);
  const caret = (view: EditorView) => (view.state.selection.main.empty ? view.state.selection.main.head : null);
  return Prec.highest(
    keymap.of([
      { key: "Tab", run: go("next"), shift: go("previous") },
      { key: "Enter", run: go("below"), shift: () => true },
      { key: "ArrowUp", run: (view) => atVerticalEdge(view, false) && host.navigate(cell, "up") },
      { key: "ArrowDown", run: (view) => atVerticalEdge(view, true) && host.navigate(cell, "down") },
      { key: "ArrowLeft", run: (view) => caret(view) === 0 && host.navigate(cell, "left") },
      { key: "ArrowRight", run: (view) => caret(view) === view.state.doc.length && host.navigate(cell, "right") },
      { key: "Mod-z", run: () => undo(host.outer), preventDefault: true },
      { key: "Mod-y", run: () => redo(host.outer), preventDefault: true },
      { key: "Mod-Shift-z", run: () => redo(host.outer), preventDefault: true },
    ]),
  );
}

function editability(editable: boolean): Extension {
  return [EditorView.editable.of(editable), EditorState.readOnly.of(!editable)];
}

/** The outer editor redraws its DOM selection on "select.pointer", which would pull focus out of the cell. */
function forwardedUserEvent(event: string | undefined) {
  return event === "select.pointer" ? "select" : event;
}

/** The outer document stays the truth: edits go out to it, and its text comes back in. */
export class CellEditor {
  readonly view: EditorView;
  private readonly editable = new Compartment();

  constructor(
    readonly host: CellHost,
    parent: HTMLElement,
    public row: number,
    public column: number,
    text: string,
    editable: boolean,
  ) {
    this.view = new EditorView({
      parent,
      state: EditorState.create({ doc: text, extensions: this.extensions(editable) }),
      dispatchTransactions: (transactions, view) => {
        const fromUser = transactions.every((transaction) => !transaction.annotation(fromTable));
        const docChanged = transactions.some((transaction) => transaction.docChanged);
        view.update(transactions);
        if (!fromUser || !(docChanged || view.hasFocus)) return;
        host.forward(this, {
          changes: transactions.map((transaction) => transaction.changes).reduce((all, next) => all.compose(next)),
          selection: view.state.selection.main,
          userEvent: forwardedUserEvent(transactions.at(-1)?.annotation(Transaction.userEvent)),
        });
      },
    });
  }

  private extensions(editable: boolean): Extension {
    return [
      cellLanguage,
      livePreview,
      markdownUrlPolicy.of(this.host.outer.state.facet(markdownUrlPolicy)),
      recipeTheme,
      EditorView.lineWrapping,
      EditorView.contentAttributes.of({ "aria-multiline": "false", "aria-labelledby": this.host.columnHeaderId(this.column) }),
      this.editable.of(editability(editable)),
      cellInput,
      cellKeymap(this),
      markdownMarkKeymap,
      editingKeymap,
    ];
  }

  get text() {
    return this.view.state.doc.toString();
  }

  /** Takes the cell's text from the outer document, changing only what differs so the caret stays put. */
  sync(text: string) {
    const current = this.text;
    if (current === text) return;
    let start = 0;
    while (start < current.length && start < text.length && current[start] === text[start]) start++;
    let end = 0;
    while (end < current.length - start && end < text.length - start && current.at(-1 - end) === text.at(-1 - end)) end++;
    this.view.dispatch({
      changes: { from: start, to: current.length - end, insert: text.slice(start, text.length - end) },
      annotations: fromTable.of(true),
    });
  }

  setEditable(editable: boolean) {
    if (this.view.state.facet(EditorView.editable) === editable) return;
    this.view.dispatch({ effects: this.editable.reconfigure(editability(editable)), annotations: fromTable.of(true) });
  }

  select(anchor: number, head = anchor) {
    const length = this.view.state.doc.length;
    const clamp = (pos: number) => Math.max(0, Math.min(length, pos));
    const selection = EditorSelection.single(clamp(anchor), clamp(head));
    if (this.view.state.selection.eq(selection)) return;
    this.view.dispatch({ selection, annotations: fromTable.of(true) });
  }

  focus(at: "start" | "end" | number) {
    const length = this.view.state.doc.length;
    const edges = { start: 0, end: length };
    const position = Math.max(0, Math.min(length, typeof at === "number" ? at : edges[at]));
    this.view.focus();
    this.view.dispatch({ selection: EditorSelection.cursor(position), userEvent: "select" });
  }

  destroy() {
    this.view.destroy();
  }
}

import { isolateHistory } from "@codemirror/commands";
import { syntaxTree } from "@codemirror/language";
import { type EditorState, type Extension, Prec, type Range, StateEffect, StateField } from "@codemirror/state";
import { type Command, Decoration, type DecorationSet, EditorView, keymap, ViewPlugin } from "@codemirror/view";
import type { MarkdownTables } from "../../engine";
import {
  alignColumn,
  appendColumn,
  appendRow,
  cellAt,
  deleteColumn,
  deleteRow,
  insertColumn,
  insertRow,
  moveColumn,
  moveRow,
  parseTable,
} from "./table-model";
import { fromCell, renderedTables, type TableLine, type TableView, TableWidget, tableViewOf } from "./table-widget";

type SelectedLine = { from: number; line: TableLine };
type LiveTables = { decorations: DecorationSet; selected: SelectedLine | null };

const selectLine = StateEffect.define<SelectedLine | null>();

function tableDecorations(state: EditorState, selected: SelectedLine | null): DecorationSet {
  const editable = state.facet(EditorView.editable);
  const ranges: Range<Decoration>[] = [];
  for (let node = syntaxTree(state).topNode.firstChild; node; node = node.nextSibling) {
    if (node.name !== "Table" || state.doc.lineAt(node.from).from !== node.from) continue;
    const to = state.doc.lineAt(node.to).to;
    const text = state.sliceDoc(node.from, to);
    if (!parseTable(text)) continue;
    const line = selected?.from === node.from ? selected.line : null;
    ranges.push(Decoration.replace({ widget: new TableWidget(text, editable, line), block: true }).range(node.from, to));
  }
  return Decoration.set(ranges);
}

/** Top-level tables render as grids of cell editors; a row or column selection lasts until the next edit or caret move. */
const liveTablesField = StateField.define<LiveTables>({
  create: (state) => ({ decorations: tableDecorations(state, null), selected: null }),
  update(value, transaction) {
    let selected = transaction.docChanged || transaction.selection ? null : value.selected;
    for (const effect of transaction.effects) if (effect.is(selectLine)) selected = effect.value;
    const editableChanged = transaction.startState.facet(EditorView.editable) !== transaction.state.facet(EditorView.editable);
    const treeChanged = syntaxTree(transaction.startState) !== syntaxTree(transaction.state);
    if (!(transaction.docChanged || editableChanged || treeChanged) && selected === value.selected) return value;
    return { decorations: tableDecorations(transaction.state, selected), selected };
  },
  provide: (field) => EditorView.decorations.from(field, (value) => value.decorations),
});

function tableAround(view: EditorView, pos: number) {
  for (const table of renderedTables(view)) {
    const range = table.range();
    if (range && pos >= range.from && pos <= range.to) return table;
  }
  return null;
}

export function activeTableCell(view: EditorView): { editor: EditorView; from: number } | null {
  for (const owner of renderedTables(view)) {
    const active = owner.activeCell();
    const cell = active && owner.model()?.rows[active.row]?.cells[active.column];
    if (active && cell) return { editor: active.editor.view, from: cell.from };
  }
  return null;
}

/** When the caret lands on a table, the cell under it takes focus: the outer editor never edits table text itself. */
const tableFocus = ViewPlugin.define((view) => ({
  update(update) {
    if (!(update.selectionSet || update.focusChanged) || update.transactions.some((transaction) => transaction.annotation(fromCell)))
      return;
    queueMicrotask(() => {
      if (!view.hasFocus) return;
      const { head } = view.state.selection.main;
      tableAround(view, head)?.focusAt(head);
    });
  },
}));

/** ArrowUp and ArrowDown enter a table in the column under the caret, like moving between lines. */
function enterVertically(forward: boolean): Command {
  return (view) => {
    const range = view.state.selection.main;
    if (!range.empty) return false;
    const table = tableAround(view, view.moveVertically(range, forward).head);
    const model = table?.model();
    if (!(table && model)) return false;
    const x = view.coordsAtPos(range.head)?.left ?? 0;
    return table.focusCell(forward ? 0 : model.rows.length - 1, table.columnAt(x), forward ? "start" : "end");
  };
}

export const liveTables: Extension = [
  liveTablesField,
  tableFocus,
  Prec.high(
    keymap.of([
      { key: "ArrowDown", run: enterVertically(true) },
      { key: "ArrowUp", run: enterVertically(false) },
    ]),
  ),
];

export function createLiveTables(view: EditorView): MarkdownTables {
  const viewOf = (table: HTMLTableElement): TableView | null => {
    const owner = tableViewOf(table);
    return owner?.outer === view ? owner : null;
  };
  const modelOf = (table: HTMLTableElement) => {
    const owner = viewOf(table);
    const model = owner?.model();
    return owner && model ? { owner, model } : null;
  };

  function caretInTables() {
    const { head } = view.state.selection.main;
    const owner = tableAround(view, head);
    const model = owner?.model();
    const address = model && cellAt(model, head);
    return owner && address ? { table: owner.table, ...address } : null;
  }

  function selectedLine() {
    const selected = view.state.field(liveTablesField, false)?.selected;
    if (!selected) return null;
    for (const owner of renderedTables(view)) {
      if (owner.range()?.from !== selected.from) continue;
      const { axis, index } = selected.line;
      return { table: owner.table, row: axis === "row" ? index : 0, column: axis === "column" ? index : 0 };
    }
    return null;
  }

  return {
    caret() {
      for (const owner of renderedTables(view)) {
        const active = owner.activeCell();
        if (active) return { table: owner.table, row: active.row, column: active.column };
      }
      return caretInTables() ?? selectedLine();
    },
    select(table, axis, index) {
      const from = viewOf(table)?.range()?.from;
      if (from !== undefined) view.dispatch({ effects: selectLine.of({ from, line: { axis, index } }) });
    },
    move(table, axis, from, to) {
      const found = modelOf(table);
      const edit = found && (axis === "row" ? moveRow(found.model, from, to) : moveColumn(found.model, from, to));
      if (!(found && edit)) return false;
      view.dispatch({
        changes: edit.changes,
        effects: selectLine.of({ from: found.model.from, line: { axis, index: to } }),
        annotations: isolateHistory.of("full"),
        userEvent: "move.table",
      });
      return true;
    },
    insert(table, axis, index, side) {
      const found = modelOf(table);
      if (!found) return;
      found.owner.apply(axis === "row" ? insertRow(found.model, index, side) : insertColumn(found.model, index, side));
    },
    remove(table, axis, index) {
      const found = modelOf(table);
      if (!found) return;
      const { model, owner } = found;
      const edit = axis === "row" ? deleteRow(model, index) : deleteColumn(model, index);
      const row = axis === "row" ? Math.min(index, model.rows.length - 2) : 0;
      const column = axis === "column" ? Math.min(index, model.columns - 2) : 0;
      owner.apply(edit, { row, column });
    },
    align(table, column, align) {
      const found = modelOf(table);
      if (found) found.owner.apply(alignColumn(found.model, column, align), { row: 0, column });
    },
    append(table, axis) {
      const found = modelOf(table);
      if (found) found.owner.apply(axis === "row" ? appendRow(found.model) : appendColumn(found.model));
    },
  };
}

import type { TextChange } from "../format/inline";

export type TableAlign = "left" | "center" | "right" | null;
export type TableCell = { from: number; to: number; text: string };
export type TableRow = { from: number; to: number; text: string; cells: TableCell[] };
export type MarkdownTableModel = {
  from: number;
  to: number;
  rows: TableRow[];
  delimiter: TableRow;
  aligns: TableAlign[];
  columns: number;
};
export type TableEdit = { changes: TextChange[]; focus?: { row: number; column: number } };

type Segment = { start: number; end: number };
type LineLayout = { prefix: string; suffix: string; segments: Segment[] };
type SourceLine = { from: number; text: string };
type SegmentTransform = (segments: string[], filler: string) => string[];

const emptyCell = "  ";
const plainDelimiter = " --- ";
const delimiterCellPattern = /^\s*:?-+:?\s*$/;

function unescapedPipes(text: string): number[] {
  const pipes: number[] = [];
  for (let index = 0; index < text.length; index++) {
    const char = text[index];
    if (char === "\\") index++;
    else if (char === "|") pipes.push(index);
  }
  return pipes;
}

function layoutLine(text: string): LineLayout {
  const pipes = unescapedPipes(text);
  const firstContent = text.search(/\S/);
  const lastContent = text.trimEnd().length - 1;
  const firstPipe = pipes.length > 0 ? pipes[0] : -1;
  const lastPipe = pipes.length > 0 ? pipes[pipes.length - 1] : -1;
  const leading = firstPipe >= 0 && firstPipe === firstContent ? firstPipe : -1;
  const trailing = lastPipe >= 0 && lastPipe === lastContent && lastPipe !== leading ? lastPipe : -1;
  const start = leading + 1;
  const end = trailing >= 0 ? trailing : text.length;
  const segments: Segment[] = [];
  let segmentStart = start;
  for (const pipe of pipes) {
    if (pipe <= leading || pipe >= end) continue;
    segments.push({ start: segmentStart, end: pipe });
    segmentStart = pipe + 1;
  }
  segments.push({ start: segmentStart, end });
  return { prefix: text.slice(0, start), suffix: text.slice(end), segments };
}

function contentCell(text: string, offset: number, segment: Segment): TableCell {
  const from = segment.start < segment.end && text[segment.start] === " " ? segment.start + 1 : segment.start;
  const to = segment.end - 1 >= from && text[segment.end - 1] === " " ? segment.end - 1 : segment.end;
  return { from: offset + from, to: offset + to, text: text.slice(from, to) };
}

function rawCell(text: string, offset: number, segment: Segment): TableCell {
  return { from: offset + segment.start, to: offset + segment.end, text: text.slice(segment.start, segment.end) };
}

function parseRow(line: SourceLine, cellOf: typeof contentCell): TableRow {
  const cells = layoutLine(line.text).segments.map((segment) => cellOf(line.text, line.from, segment));
  return { from: line.from, to: line.from + line.text.length, text: line.text, cells };
}

function splitLines(text: string, offset: number): SourceLine[] {
  const lines: SourceLine[] = [];
  let from = offset;
  for (const lineText of text.split("\n")) {
    lines.push({ from, text: lineText });
    from += lineText.length + 1;
  }
  return lines;
}

function alignOf(segment: string): TableAlign {
  const marker = segment.trim();
  const left = marker.startsWith(":");
  const right = marker.endsWith(":");
  if (left && right) return "center";
  if (right) return "right";
  return left ? "left" : null;
}

function isDelimiterRow(row: TableRow, columns: number): boolean {
  return (
    unescapedPipes(row.text).length > 0 && row.cells.length === columns && row.cells.every((cell) => delimiterCellPattern.test(cell.text))
  );
}

export function parseTable(text: string, offset = 0): MarkdownTableModel | null {
  const [headerLine, delimiterLine, ...bodyLines] = splitLines(text, offset);
  if (!headerLine || !delimiterLine || unescapedPipes(headerLine.text).length === 0) return null;
  const header = parseRow(headerLine, contentCell);
  const delimiter = parseRow(delimiterLine, rawCell);
  const columns = header.cells.length;
  if (!isDelimiterRow(delimiter, columns)) return null;
  const blankIndex = bodyLines.findIndex((line) => line.text.trim() === "");
  const body = (blankIndex < 0 ? bodyLines : bodyLines.slice(0, blankIndex)).map((line) => parseRow(line, contentCell));
  const rows = [header, ...body];
  const lastLine = body.length > 0 ? body[body.length - 1] : delimiter;
  return { from: header.from, to: lastLine.to, rows, delimiter, aligns: delimiter.cells.map((cell) => alignOf(cell.text)), columns };
}

function columnAt(row: TableRow, pos: number): number {
  const contentIndex = row.cells.findIndex((cell) => pos >= cell.from && pos <= cell.to);
  if (contentIndex >= 0) return contentIndex;
  const segments = layoutLine(row.text).segments;
  const rawIndex = segments.findIndex((segment) => pos >= row.from + segment.start && pos <= row.from + segment.end);
  if (rawIndex >= 0) return rawIndex;
  return pos < row.from + segments[0].start ? 0 : segments.length - 1;
}

export function cellAt(table: MarkdownTableModel, pos: number): { row: number; column: number } | null {
  const rowIndex = table.rows.findIndex((row) => pos >= row.from && pos <= row.to);
  if (rowIndex < 0) return null;
  return { row: rowIndex, column: columnAt(table.rows[rowIndex], pos) };
}

function joinLine(prefix: string, segments: string[], suffix: string): string {
  const first = segments.length > 0 ? segments[0] : "";
  const last = segments.length > 0 ? segments[segments.length - 1] : "";
  const start = prefix === "" && first.trim() === "" ? "|" : prefix;
  const end = suffix === "" && (last.trim() === "" || (start === "" && segments.length < 2)) ? "|" : suffix;
  return `${start}${segments.join("|")}${end}`;
}

function padded(segments: string[], length: number, filler: string): string[] {
  const missing = Math.max(0, length - segments.length);
  return [...segments, ...Array.from({ length: missing }, () => filler)];
}

function rebuildRow(row: TableRow, filler: string, transform: SegmentTransform): TextChange | null {
  const layout = layoutLine(row.text);
  const segments = layout.segments.map((segment) => row.text.slice(segment.start, segment.end));
  const text = joinLine(layout.prefix, transform(segments, filler), layout.suffix);
  return text === row.text ? null : { from: row.from, to: row.to, insert: text };
}

function columnChanges(table: MarkdownTableModel, transform: SegmentTransform): TextChange[] {
  const [header, ...body] = table.rows;
  const lines = [
    rebuildRow(header, emptyCell, transform),
    rebuildRow(table.delimiter, plainDelimiter, transform),
    ...body.map((row) => rebuildRow(row, emptyCell, transform)),
  ];
  return lines.filter((change): change is TextChange => change !== null);
}

function isIndex(index: number, length: number): boolean {
  return Number.isInteger(index) && index >= 0 && index < length;
}

function newRowText(table: MarkdownTableModel): string {
  const header = layoutLine(table.rows[0].text);
  const cells = Array.from({ length: table.columns }, () => emptyCell);
  return joinLine(header.prefix === "" ? "" : "|", cells, header.suffix === "" ? "" : "|");
}

function lineEndOfRow(table: MarkdownTableModel, index: number): number {
  return index === 0 ? table.delimiter.to : table.rows[index].to;
}

export function moveRow(table: MarkdownTableModel, from: number, to: number): TableEdit | null {
  const length = table.rows.length;
  if (from === to || from < 1 || to < 1 || !isIndex(from, length) || !isIndex(to, length)) return null;
  const texts = table.rows.map((row) => row.text);
  texts.splice(to, 0, ...texts.splice(from, 1));
  const low = Math.min(from, to);
  const high = Math.max(from, to);
  const insert = texts.slice(low, high + 1).join("\n");
  return { changes: [{ from: table.rows[low].from, to: table.rows[high].to, insert }], focus: { row: to, column: 0 } };
}

export function moveColumn(table: MarkdownTableModel, from: number, to: number): TableEdit | null {
  if (from === to || !isIndex(from, table.columns) || !isIndex(to, table.columns)) return null;
  const changes = columnChanges(table, (segments, filler) => {
    const next = padded(segments, Math.max(from, to) + 1, filler);
    next.splice(to, 0, ...next.splice(from, 1));
    return next;
  });
  return { changes, focus: { row: 0, column: to } };
}

export function insertRow(table: MarkdownTableModel, index: number, side: "before" | "after"): TableEdit | null {
  if (!isIndex(index, table.rows.length)) return null;
  const text = newRowText(table);
  if (side === "after") {
    const at = lineEndOfRow(table, index);
    return { changes: [{ from: at, to: at, insert: `\n${text}` }], focus: { row: index + 1, column: 0 } };
  }
  if (index === 0) return null;
  const at = table.rows[index].from;
  return { changes: [{ from: at, to: at, insert: `${text}\n` }], focus: { row: index, column: 0 } };
}

function insertColumnAt(table: MarkdownTableModel, at: number): TableEdit {
  const changes = columnChanges(table, (segments, filler) => {
    const next = padded(segments, at, filler);
    next.splice(at, 0, filler);
    return next;
  });
  return { changes, focus: { row: 0, column: at } };
}

export function insertColumn(table: MarkdownTableModel, index: number, side: "before" | "after"): TableEdit | null {
  if (!isIndex(index, table.columns)) return null;
  return insertColumnAt(table, side === "before" ? index : index + 1);
}

export function deleteRow(table: MarkdownTableModel, index: number): TableEdit | null {
  if (index < 1 || !isIndex(index, table.rows.length)) return null;
  return { changes: [{ from: lineEndOfRow(table, index - 1), to: table.rows[index].to, insert: "" }] };
}

export function deleteColumn(table: MarkdownTableModel, index: number): TableEdit | null {
  if (table.columns < 2 || !isIndex(index, table.columns)) return null;
  const changes = columnChanges(table, (segments) => {
    if (segments.length <= index) return segments;
    const next = segments.filter((_, column) => column !== index);
    return next.length > 0 ? next : [emptyCell];
  });
  return { changes };
}

function delimiterSegment(align: TableAlign): string {
  if (align === "left") return " :--- ";
  if (align === "center") return " :---: ";
  if (align === "right") return " ---: ";
  return plainDelimiter;
}

export function alignColumn(table: MarkdownTableModel, index: number, align: TableAlign): TableEdit | null {
  if (!isIndex(index, table.columns)) return null;
  const segment = table.delimiter.cells[index];
  const insert = delimiterSegment(align);
  return { changes: segment.text === insert ? [] : [{ from: segment.from, to: segment.to, insert }] };
}

export function appendRow(table: MarkdownTableModel): TableEdit {
  return { changes: [{ from: table.to, to: table.to, insert: `\n${newRowText(table)}` }], focus: { row: table.rows.length, column: 0 } };
}

export function appendColumn(table: MarkdownTableModel): TableEdit {
  return insertColumnAt(table, table.columns);
}

export function createTableMarkdown(columns: number, bodyRows: number): string {
  const count = Math.max(1, Math.floor(columns));
  const line = (segment: string) => `|${Array.from({ length: count }, () => segment).join("|")}|`;
  const body = Array.from({ length: Math.max(0, Math.floor(bodyRows)) }, () => line(emptyCell));
  return [line(emptyCell), line(plainDelimiter), ...body].join("\n");
}

export function escapeCellText(text: string): string {
  return text.replace(/\r\n|\r|\n/g, " ").replace(/\\[\s\S]|\|/g, (match) => (match === "|" ? "\\|" : match));
}

import { isolateHistory } from "@codemirror/commands";
import { Annotation, type ChangeSpec, EditorSelection, type TransactionSpec } from "@codemirror/state";
import { type EditorView, WidgetType } from "@codemirror/view";
import type { MarkdownTableAxis } from "../../engine";
import { type CellEdit, CellEditor, type CellHost, type CellMove } from "./cell-editor";
import { appendRow, cellAt, type MarkdownTableModel, parseTable, type TableEdit } from "./table-model";

export type TableLine = { axis: MarkdownTableAxis; index: number };
export type TableCellAddress = { row: number; column: number };

/** Marks outer transactions that a cell editor made, so they never bounce back into it. */
export const fromCell = Annotation.define<true>();

const tablesByView = new WeakMap<EditorView, Set<TableView>>();
const tablesByDom = new WeakMap<HTMLElement, TableView>();

export function renderedTables(outer: EditorView): ReadonlySet<TableView> {
  return tablesByView.get(outer) ?? new Set();
}

export function tableViewOf(element: HTMLElement): TableView | null {
  return tablesByDom.get(element) ?? null;
}

function neighbour(move: CellMove, at: TableCellAddress, last: TableCellAddress): TableCellAddress | null {
  const { row, column } = at;
  if (move === "up") return row > 0 ? { row: row - 1, column } : null;
  if (move === "down" || move === "below") return row < last.row ? { row: row + 1, column } : null;
  if (move === "next" || move === "right") {
    if (column < last.column) return { row, column: column + 1 };
    return row < last.row ? { row: row + 1, column: 0 } : null;
  }
  if (column > 0) return { row, column: column - 1 };
  return row > 0 ? { row: row - 1, column: last.column } : null;
}

/** Leaving a table at the document's edge opens a paragraph there, so text can always be written around it. */
function exitBefore(model: MarkdownTableModel): TransactionSpec {
  if (model.from > 0) return { selection: EditorSelection.cursor(model.from - 1) };
  return { changes: { from: 0, insert: "\n\n" }, selection: EditorSelection.cursor(0) };
}

function exitAfter(model: MarkdownTableModel, length: number): TransactionSpec {
  if (model.to < length) return { selection: EditorSelection.cursor(model.to + 1) };
  return { changes: { from: model.to, insert: "\n\n" }, selection: EditorSelection.cursor(model.to + 2) };
}

let renderedTableCount = 0;

export class TableView implements CellHost {
  readonly dom = document.createElement("div");
  readonly table = document.createElement("table");
  private readonly head = this.table.createTHead();
  private readonly body = this.table.createTBody();
  private readonly editors = new Map<HTMLTableCellElement, CellEditor>();
  private text = "";
  private editable = true;
  private readonly id = `cm-md-table-${++renderedTableCount}`;

  constructor(readonly outer: EditorView) {
    this.dom.className = "cm-md-table";
    this.dom.append(this.table);
    this.table.addEventListener("mousedown", this.focusFromPadding);
    tablesByDom.set(this.dom, this);
    tablesByDom.set(this.table, this);
    const tables = tablesByView.get(outer) ?? new Set();
    tables.add(this);
    tablesByView.set(outer, tables);
  }

  /** The table's document range; read it outside view updates only. */
  range() {
    if (!this.dom.isConnected) return null;
    const from = this.outer.posAtDOM(this.dom);
    return { from, to: from + this.text.length };
  }

  model(): MarkdownTableModel | null {
    const range = this.range();
    return range && parseTable(this.outer.state.sliceDoc(range.from, range.to), range.from);
  }

  render(text: string, editable: boolean, line: TableLine | null) {
    this.text = text;
    this.editable = editable;
    const model = parseTable(text);
    if (!model) return;
    this.resize(model.rows.length, model.columns);
    for (const [rowIndex, row] of model.rows.entries()) {
      for (let column = 0; column < model.columns; column++) {
        const element = this.cellElement(rowIndex, column);
        if (!element) continue;
        const selected = line !== null && (line.axis === "row" ? line.index === rowIndex : line.index === column);
        element.classList.toggle("selectedCell", selected);
        element.style.textAlign = model.aligns[column] ?? "";
        this.renderCell(element, rowIndex, column, row.cells[column]?.text ?? null);
      }
    }
    queueMicrotask(this.followSelection);
  }

  private renderCell(element: HTMLTableCellElement, row: number, column: number, text: string | null) {
    const editor = this.editors.get(element);
    if (text === null) {
      editor?.destroy();
      this.editors.delete(element);
      element.dataset.missing = "";
      return;
    }
    delete element.dataset.missing;
    if (!editor) {
      this.editors.set(element, new CellEditor(this, element, row, column, text, this.editable));
      return;
    }
    editor.row = row;
    editor.column = column;
    editor.sync(text);
    editor.setEditable(this.editable);
  }

  private resize(rows: number, columns: number) {
    const head = this.head.rows[0] ?? this.head.insertRow();
    while (this.body.rows.length > rows - 1) this.removeRow(this.body.rows[this.body.rows.length - 1]);
    while (this.body.rows.length < rows - 1) this.body.insertRow();
    for (const row of [head, ...Array.from(this.body.rows)]) {
      while (row.cells.length > columns) this.removeCell(row.cells[row.cells.length - 1]);
      while (row.cells.length < columns) row.append(this.createCell(row === head, row.cells.length));
    }
  }

  private removeRow(row: HTMLTableRowElement) {
    for (const cell of Array.from(row.cells)) this.removeCell(cell);
    row.remove();
  }

  private removeCell(cell: HTMLTableCellElement) {
    this.editors.get(cell)?.destroy();
    this.editors.delete(cell);
    cell.remove();
  }

  private createCell(header: boolean, column: number) {
    const cell = document.createElement(header ? "th" : "td");
    if (header) cell.id = this.columnHeaderId(column);
    return cell;
  }

  columnHeaderId(column: number) {
    return `${this.id}-column-${column}`;
  }

  private cellElement(row: number, column: number): HTMLTableCellElement | null {
    return this.table.rows[row]?.cells[column] ?? null;
  }

  activeCell(): (TableCellAddress & { editor: CellEditor }) | null {
    for (const editor of this.editors.values()) {
      if (editor.view.hasFocus) return { row: editor.row, column: editor.column, editor };
    }
    return null;
  }

  focusCell(row: number, column: number, at: "start" | "end" | number = "end") {
    const element = this.cellElement(row, column);
    const editor = element && this.editors.get(element);
    if (!editor) return false;
    editor.focus(at);
    return true;
  }

  focusAt(pos: number) {
    const model = this.model();
    const address = model && cellAt(model, pos);
    const cell = address && model.rows[address.row]?.cells[address.column];
    if (!(address && cell)) return false;
    return this.focusCell(address.row, address.column, Math.max(0, Math.min(cell.to, pos) - cell.from));
  }

  columnAt(x: number) {
    const cells = Array.from(this.table.rows[0]?.cells ?? []);
    const index = cells.findIndex((cell) => x < cell.getBoundingClientRect().right);
    return index < 0 ? Math.max(0, cells.length - 1) : index;
  }

  /** After the outer document changed, a focused cell takes the outer selection when that selection lies in this table. */
  private followSelection = () => {
    const active = this.activeCell();
    const model = active ? this.model() : null;
    if (!(active && model)) return;
    const { anchor, head } = this.outer.state.selection.main;
    if (head < model.from || head > model.to) return;
    const address = cellAt(model, head);
    const cell = address && model.rows[address.row]?.cells[address.column];
    if (!(address && cell)) return;
    if (address.row !== active.row || address.column !== active.column) {
      this.focusCell(address.row, address.column, head - cell.from);
      return;
    }
    const clamp = (pos: number) => Math.max(cell.from, Math.min(cell.to, pos)) - cell.from;
    active.editor.select(clamp(anchor), clamp(head));
  };

  /** Applies a table edit as one undo step, then puts the caret in the cell it names. */
  apply(edit: TableEdit | null, focus: TableCellAddress | null = edit?.focus ?? null) {
    if (!edit) return false;
    this.outer.dispatch({ changes: edit.changes, annotations: isolateHistory.of("full"), userEvent: "input.table" });
    if (focus) this.focusCell(focus.row, focus.column);
    return true;
  }

  forward(cell: CellEditor, edit: CellEdit) {
    const target = this.model()?.rows[cell.row]?.cells[cell.column];
    if (!target) return;
    if (edit.changes.length !== target.to - target.from) {
      cell.sync(target.text);
      return;
    }
    const changes: ChangeSpec[] = [];
    edit.changes.iterChanges((from, to, _fromB, _toB, inserted) => {
      changes.push({ from: target.from + from, to: target.from + to, insert: inserted.toString() });
    });
    this.outer.dispatch({
      changes,
      selection: EditorSelection.single(target.from + edit.selection.anchor, target.from + edit.selection.head),
      annotations: fromCell.of(true),
      userEvent: edit.userEvent,
    });
  }

  navigate(cell: CellEditor, move: CellMove) {
    const model = this.model();
    if (!model) return false;
    const at = { row: cell.row, column: cell.column };
    const target = neighbour(move, at, { row: model.rows.length - 1, column: model.columns - 1 });
    if (target) return this.focusCell(target.row, target.column, move === "down" || move === "right" ? "start" : "end");
    if (move === "next") return this.apply(appendRow(model), { row: model.rows.length, column: 0 });
    if (move === "below") return this.apply(appendRow(model), { row: model.rows.length, column: at.column });
    if (move === "previous") return true;
    return this.exit(model, move === "up" || move === "left" ? -1 : 1);
  }

  private exit(model: MarkdownTableModel, direction: -1 | 1) {
    const exit = direction < 0 ? exitBefore(model) : exitAfter(model, this.outer.state.doc.length);
    this.outer.dispatch({ ...exit, scrollIntoView: true });
    this.outer.focus();
    return true;
  }

  private focusFromPadding = (event: MouseEvent) => {
    const cell = event.target instanceof HTMLTableCellElement ? event.target : null;
    const editor = cell && this.editors.get(cell);
    if (!editor) return;
    event.preventDefault();
    editor.focus("end");
  };

  destroy() {
    for (const editor of this.editors.values()) editor.destroy();
    this.editors.clear();
    tablesByView.get(this.outer)?.delete(this);
  }
}

export class TableWidget extends WidgetType {
  constructor(
    readonly text: string,
    readonly writable: boolean,
    readonly line: TableLine | null,
  ) {
    super();
  }

  eq(other: TableWidget) {
    return (
      other.text === this.text &&
      other.writable === this.writable &&
      other.line?.axis === this.line?.axis &&
      other.line?.index === this.line?.index
    );
  }

  toDOM(view: EditorView) {
    const table = new TableView(view);
    table.render(this.text, this.writable, this.line);
    return table.dom;
  }

  updateDOM(dom: HTMLElement, view: EditorView) {
    const table = tableViewOf(dom);
    if (table?.outer !== view) return false;
    table.render(this.text, this.writable, this.line);
    return true;
  }

  destroy(dom: HTMLElement) {
    tableViewOf(dom)?.destroy();
  }
}

import { type EditorState, StateEffect, StateField, type Text, Transaction } from "@codemirror/state";
import { Decoration, EditorView, WidgetType } from "@codemirror/view";
import type { MarkdownUploadPlaceholders } from "../engine";
import { enclosingNode } from "./format/inline";
import { imageMarkdown } from "./format/links";

type Placeholder = { id: string; name: string; pos: number };

const addPlaceholder = StateEffect.define<Placeholder>();
const dropPlaceholder = StateEffect.define<string>();
export const clearPlaceholders = StateEffect.define<null>();

class PlaceholderWidget extends WidgetType {
  constructor(readonly name: string) {
    super();
  }

  eq(other: PlaceholderWidget) {
    return other.name === this.name;
  }

  toDOM() {
    const element = document.createElement("div");
    element.dataset.imageUpload = "";
    element.setAttribute("role", "status");
    element.textContent = `Image: ${this.name}`;
    return element;
  }
}

function placeholderDecorations(state: EditorState, placeholders: readonly Placeholder[]) {
  return Decoration.set(
    placeholders.map((placeholder) => {
      const line = state.doc.lineAt(placeholder.pos);
      const before = placeholder.pos === line.from;
      return Decoration.widget({ widget: new PlaceholderWidget(placeholder.name), block: true, side: before ? -1 : 1 }).range(
        before ? line.from : line.to,
      );
    }),
    true,
  );
}

/** Placeholders stand before the line they were dropped on, mapped through edits, and never enter the Markdown. */
export const uploadPlaceholders = StateField.define<readonly Placeholder[]>({
  create: () => [],
  update(value, transaction) {
    let next = transaction.docChanged
      ? value.map((placeholder) => ({ ...placeholder, pos: transaction.changes.mapPos(placeholder.pos, -1) }))
      : value;
    for (const effect of transaction.effects) {
      if (effect.is(addPlaceholder)) next = [...next, effect.value];
      else if (effect.is(dropPlaceholder)) next = next.filter((placeholder) => placeholder.id !== effect.value);
      else if (effect.is(clearPlaceholders)) next = [];
    }
    return next;
  },
  provide: (field) => EditorView.decorations.compute([field], (state) => placeholderDecorations(state, state.field(field))),
});

const isBlank = (doc: Text, number: number) => number >= 1 && number <= doc.lines && doc.line(number).text.trim() === "";

/** A pending image waits on a blank line, or before the line after the one it was dropped on. */
function anchorAt(doc: Text, pos: number) {
  const line = doc.lineAt(pos);
  if (line.text.trim() === "") return line.from;
  return line.number < doc.lines ? line.to + 1 : line.to;
}

/** The image becomes its own paragraph: it fills a blank line, or is set apart from its neighbours by blank lines. */
function blockInsertion(doc: Text, pos: number, text: string) {
  const line = doc.lineAt(pos);
  const hasBefore = line.number > 1 && !isBlank(doc, line.number - 1);
  const hasAfter = line.number < doc.lines && !isBlank(doc, line.number + 1);
  if (line.text.trim() === "") return { from: line.from, to: line.to, insert: `${hasBefore ? "\n" : ""}${text}${hasAfter ? "\n" : ""}` };
  if (pos === line.from) return { from: pos, insert: `${hasBefore ? "\n" : ""}${text}\n\n` };
  return { from: line.to, insert: `\n\n${text}` };
}

export function createLiveUploads(view: EditorView): MarkdownUploadPlaceholders {
  const find = (id: string) => view.state.field(uploadPlaceholders).find((placeholder) => placeholder.id === id);
  return {
    insert(id, name, at) {
      const target = at ?? view.state.selection.main.to;
      const table = enclosingNode(view.state, { from: target, to: target }, "Table");
      const pos = anchorAt(view.state.doc, table ? table.to : target);
      view.dispatch({ effects: addPlaceholder.of({ id, name, pos }) });
    },
    complete(id, image) {
      const placeholder = find(id);
      if (!placeholder) return;
      const markdown = imageMarkdown({ src: image.url, alt: image.alt, title: image.title });
      view.dispatch({
        changes: blockInsertion(view.state.doc, placeholder.pos, markdown),
        effects: dropPlaceholder.of(id),
        annotations: Transaction.addToHistory.of(false),
      });
    },
    remove(id) {
      if (find(id)) view.dispatch({ effects: dropPlaceholder.of(id) });
    },
    has: (id) => find(id) !== undefined,
  };
}

@layer components {
  :where([data-control-family="markdown-editor"] :is(.tiptap .tableWrapper, .cm-md-table)) {
    overflow-x: auto;
    overscroll-behavior-inline: contain;
  }
  :where([data-control-family="markdown-editor"] :is(.tiptap, .cm-md-table) table) {
    border-collapse: collapse;
    inline-size: auto;
  }
  :where([data-control-family="markdown-editor"] :is(.tiptap, .cm-md-table) :is(td, th)) {
    border: var(--cui-markdown-editor-table-border-width) solid var(--cui-markdown-editor-table-border-color);
    padding: calc(var(--spacing) * 1.5) calc(var(--spacing) * 2.5);
    text-align: start;
    vertical-align: top;
  }
  :where([data-control-family="markdown-editor"] :is(.tiptap :is(td, th) > p, .cm-md-table :is(td, th) > .cm-editor)) {
    min-inline-size: 4rem;
    max-inline-size: 24rem;
  }
  :where([data-control-family="markdown-editor"] :is(.tiptap, .cm-md-table) th) {
    font-weight: var(--font-weight-semibold);
  }
  :where([data-control-family="markdown-editor"] :is(.tiptap, .cm-md-table) .selectedCell) {
    background: var(--cui-markdown-editor-table-selection-background);
  }
  :where([data-control-family="markdown-editor"][data-slot="table-controls"]) {
    display: contents;
  }
  :where([data-control-family="markdown-editor"] [data-markdown-table-grip]) {
    z-index: 1;
    translate: -50% -50%;
    cursor: grab;
  }
  :where([data-control-family="markdown-editor"] [data-markdown-table-grip][data-dragging]) {
    cursor: grabbing;
  }
  :where([data-control-family="markdown-editor"] [data-markdown-table-add]) {
