  :where([data-control-family="markdown-editor"][data-slot="table-drop-line"]) {
    position: absolute;
    z-index: 1;
    border-radius: 9999px;
    background: var(--cui-markdown-editor-muted-foreground);
    pointer-events: none;
  }
  :where([data-control-family="markdown-editor"][data-slot="table-drop-line"][data-axis="row"]) {
    block-size: 2px;
    translate: 0 -50%;
  }
  :where([data-control-family="markdown-editor"][data-slot="table-drop-line"][data-axis="column"]) {
    inline-size: 2px;
    translate: -50% 0;
  }
}

@layer components {
  :where([data-control-family="markdown-editor"][data-slot="root"]) {
    --cui-markdown-editor-background: var(--background);
    --cui-markdown-editor-foreground: var(--foreground);
    --cui-markdown-editor-border-width: var(--control-rim-width);
    --cui-markdown-editor-border-color: var(--border);
    --cui-markdown-editor-focus-border-color: var(--focus-rim);
    --cui-markdown-editor-radius: var(--radius-panel);
    --cui-markdown-editor-padding: calc(var(--spacing) * 4);
    --cui-markdown-editor-gutter-size: var(--control-h-xs);
    --cui-markdown-editor-min-height: calc(var(--spacing) * 32);
    --cui-markdown-editor-max-height: 60dvh;
    --cui-markdown-editor-gap: calc(var(--spacing) * 3);
    --cui-markdown-editor-muted-foreground: var(--muted-foreground);
    --cui-markdown-editor-code-background: var(--muted);
    --cui-markdown-editor-table-border-width: var(--control-rim-width);
    --cui-markdown-editor-table-border-color: var(--border);
    --cui-markdown-editor-table-selection-background: var(--active-fill);
    color: var(--cui-markdown-editor-foreground);
    background: var(--cui-markdown-editor-background);
    border: var(--cui-markdown-editor-border-width) solid var(--cui-markdown-editor-border-color);
    border-radius: var(--cui-markdown-editor-radius);
    transition: border-color var(--duration-fast) var(--ease-standard);
    overflow: clip;
    font-size: var(--text-body);
    line-height: var(--leading-relaxed);
  }
  :where([data-control-family="markdown-editor"][data-slot="content"]) {
    position: relative;
    max-block-size: var(--cui-markdown-editor-max-height);
    overflow: auto;
  }
  :where([data-control-family="markdown-editor"][data-slot="content"] :is(.tiptap, .cm-content:not(.cm-md-table *))) {
    min-block-size: var(--cui-markdown-editor-min-height);
    padding: var(--cui-markdown-editor-padding);
    padding-inline-start: calc(var(--cui-markdown-editor-padding) + var(--cui-markdown-editor-gutter-size));
    overflow-wrap: anywhere;
    white-space: pre-wrap;
    outline: none;
  }
  :where(
    [data-control-family="markdown-editor"][data-slot="root"][data-disabled]
      [data-slot="content"]
      :is(.tiptap, .cm-content:not(.cm-md-table *))
  ) {
    opacity: var(--disabled-opacity);
    cursor: not-allowed;
  }
  :where(
    [data-control-family="markdown-editor"][data-slot="root"]:has(
      :is([data-slot="content"] :is(.tiptap, .cm-content), [data-slot="source"] textarea):focus-visible
    ):not([data-control-family="chat-composer"][data-slot="shell"] *)
  ) {
    border-color: var(--cui-markdown-editor-focus-border-color);
  }
  @media (forced-colors: active) {
    :where(
        [data-control-family="markdown-editor"][data-slot="root"]:has(
          :is([data-slot="content"] :is(.tiptap, .cm-content), [data-slot="source"] textarea):focus-visible
        ):not([data-control-family="chat-composer"][data-slot="shell"] *)
      ) {
      outline: var(--focus-ring-width) solid Highlight;
      outline-offset: calc(var(--focus-ring-width) * -1);
    }
  }
  :where([data-control-family="markdown-editor"][data-slot="toolbar"]) {
    min-inline-size: 0;
    border-block-end: var(--cui-markdown-editor-border-width) solid var(--cui-markdown-editor-border-color);
  }
  :where([data-control-family="markdown-editor"][data-slot="toolbar"] [data-control-family="toolbar"][data-slot="root"]) {
    padding-inline: var(--cui-markdown-editor-padding);
    white-space: nowrap;
  }
  :where([data-control-family="markdown-editor"][data-slot="bubble-menu"]) {
    white-space: nowrap;
  }
  :where([data-control-family="markdown-editor"][data-slot="bubble-menu"] > [data-control-family="toolbar"][data-slot="root"]) {
    --cui-toolbar-item-radius: max(0px, calc(var(--cui-popup-radius) - var(--cui-toolbar-padding)));
  }
  :where([data-control-family="markdown-editor"] [data-markdown-drag-handle]) {
    position: absolute;
    inset-inline-start: calc(var(--cui-markdown-editor-padding) / 2);
    inset-block-start: 0;
    translate: 0 var(--cui-markdown-editor-padding);
    cursor: grab;
    opacity: 0;
    pointer-events: none;
    transition-property: scale, opacity;
  }
  :where([data-control-family="markdown-editor"] [data-markdown-drag-handle][data-glide]) {
    transition-property: scale, translate, opacity;
  }
  :where([data-control-family="markdown-editor"] [data-markdown-drag-handle]:is([data-visible], :focus-visible)) {
    opacity: 1;
    pointer-events: auto;
  }
  :where([data-control-family="markdown-editor"] [data-markdown-drag-handle]:active) {
    cursor: grabbing;
  }
  :where([data-control-family="markdown-editor"][data-slot="source"] textarea) {
    --focus-ring-width: 0px;
    min-block-size: var(--cui-markdown-editor-min-height);
    max-block-size: var(--cui-markdown-editor-max-height);
    padding: 0;
    font-family: var(--font-mono);
  }
  :where([data-control-family="markdown-editor"][data-slot="source"]),
  :where([data-control-family="markdown-editor"][data-slot="uploads"]) {
    padding: var(--cui-markdown-editor-padding);
  }
  :where([data-control-family="markdown-editor"] .tiptap > * + *) {
    margin-block-start: var(--cui-markdown-editor-gap);
  }
  :where([data-control-family="markdown-editor"] .tiptap:has(> p:only-child > br:only-child))::before {
    content: attr(data-placeholder);
    color: var(--cui-markdown-editor-muted-foreground);
    pointer-events: none;
    float: inline-start;
    block-size: 0;
  }
  :where([data-control-family="markdown-editor"] .cm-placeholder) {
    color: var(--cui-markdown-editor-muted-foreground);
  }
  :where([data-control-family="markdown-editor"] .tiptap :is(h1, h2, h3, h4, h5, h6)) {
    margin-block: var(--cui-markdown-editor-gap) 0;
  }
  :where([data-control-family="markdown-editor"] .tiptap > :first-child) {
    margin-block-start: 0;
  }
  :where([data-control-family="markdown-editor"] :is(.tiptap, .cm-content) strong) {
    font-weight: var(--font-weight-semibold);
  }
  :where([data-control-family="markdown-editor"] :is(.tiptap, .cm-content) em) {
    font-style: italic;
  }
  :where([data-control-family="markdown-editor"] :is(.tiptap, .cm-content) s) {
    text-decoration: line-through;
  }
  :where([data-control-family="markdown-editor"] :is(.tiptap, .cm-content) a) {
    text-decoration: underline;
    color: var(--primary-text);
  }
  :where([data-control-family="markdown-editor"] .tiptap ul) {
    list-style: disc;
    padding-inline-start: calc(var(--spacing) * 6);
  }
  :where([data-control-family="markdown-editor"] .tiptap ol) {
    list-style: decimal;
    padding-inline-start: calc(var(--spacing) * 6);
  }
  :where([data-control-family="markdown-editor"] .tiptap ul[data-type="taskList"]) {
    list-style: none;
    padding-inline-start: 0;
