    gap: var(--cui-markdown-editor-gap);
  }
  :where([data-control-family="markdown-editor"] :is(.tiptap, .cm-content) [data-slot="task-checkbox"]) {
    display: inline-flex;
    align-items: center;
    block-size: 1lh;
    flex-shrink: 0;
  }
  :where([data-control-family="markdown-editor"] .cm-content [data-slot="task-checkbox"]) {
    vertical-align: top;
    margin-inline-end: calc(var(--spacing) * 2);
  }
  :where([data-control-family="markdown-editor"] .tiptap [data-slot="task-content"]) {
    flex: 1;
    min-inline-size: 0;
  }
